import { memo, useEffect, useMemo, useRef, useState } from 'react'
import { Play, Info } from 'lucide-react'
import Autoplay from 'embla-carousel-autoplay'
import { NavLink } from 'react-router'

import { getBackdropUrl, getLogoUrl } from '@/shared/lib/tmdb'
import { buildTmdbDetailPath, buildTmdbPlayPath } from '@/shared/lib/routes'
import { buildHistoryPlayPath, isTmdbHistoryItem } from '@/shared/lib/viewingHistory'
import { Button } from '@/shared/components/ui/button'
import {
  Carousel,
  CarouselContent,
  CarouselItem,
  type CarouselApi,
} from '@/shared/components/ui/carousel'
import { AspectRatio } from '@/shared/components/ui/aspect-ratio'
import { Skeleton } from '@/shared/components/ui/skeleton'
import { useIsMobile } from '@/shared/hooks/use-mobile'
import { useViewingHistoryStore } from '@/shared/store/viewingHistoryStore'
import type { TmdbMediaItem } from '@/shared/types/tmdb'
import type { ViewingHistoryItem } from '@/shared/types/video'

interface FeaturedCarouselProps {
  items: TmdbMediaItem[]
  loading?: boolean
  autoplayDelay?: number
}

/**
 * FeaturedCarouselItem - 单个轮播项，memo 隔离使 activeIndex 变化只重渲染当前项
 */
const FeaturedCarouselItem = memo(function FeaturedCarouselItem({
  item,
  isActive,
  getAspectRatio,
  isMobile,
  latestTmdbHistoryMap,
}: {
  item: TmdbMediaItem
  isActive: boolean
  getAspectRatio: () => number
  isMobile: boolean
  latestTmdbHistoryMap: Map<string, ViewingHistoryItem>
}) {
  const playPath = buildTmdbPlayPath(item.mediaType, item.id)
  const detailPath = buildTmdbDetailPath(item.mediaType, item.id)
  const latestTmdbHistory = latestTmdbHistoryMap.get(`${item.mediaType}-${item.id}`)
  const continueWatchingLabel = latestTmdbHistory
    ? latestTmdbHistory.episodeName || `第${latestTmdbHistory.episodeIndex + 1}集`
    : ''
  const continueWatchingProgressLabel = latestTmdbHistory
    ? latestTmdbHistory.duration > 0
      ? `已观看 ${Math.round(
          Math.min(
            100,
            Math.max(0, (latestTmdbHistory.playbackPosition / latestTmdbHistory.duration) * 100),
          ),
        )}%`
      : '已开始观看'
    : ''
  const continueWatchingPath = latestTmdbHistory
    ? latestTmdbHistory.sourceCode && latestTmdbHistory.vodId
      ? buildHistoryPlayPath(latestTmdbHistory)
      : buildTmdbPlayPath(item.mediaType, item.id, {
          episodeIndex: latestTmdbHistory.episodeIndex,
          seasonNumber: item.mediaType === 'tv' ? latestTmdbHistory.tmdbSeasonNumber ?? undefined : undefined,
        })
    : ''
  const playNowLabel = continueWatchingPath ? '从头播放' : '立即播放'

  return (
    <CarouselItem className="h-fit rounded-lg">
      <AspectRatio ratio={getAspectRatio()} className="bg-muted overflow-hidden rounded-lg">
        {/* 背景图片：始终加载 img，非 active 用 content-visibility 延迟解码 */}
        <img
          className="h-full w-full rounded-lg object-cover object-center md:object-top-right"
          src={getBackdropUrl(item.backdropPath) || undefined}
          alt={item.title}
          loading={isActive ? undefined : 'lazy'}
          fetchPriority={isActive ? 'high' : undefined}
          style={{ contentVisibility: isActive ? 'visible' : 'auto' }}
        />

        {/* 遮罩层 - 移动端/平板从下到上渐变 */}
        <div
          className={`absolute inset-0 flex min-h-0 flex-col justify-end rounded-lg bg-gradient-to-t from-black/90 via-black/50 via-60% to-transparent px-6 pt-4 pb-6 transition-opacity duration-500 ease-out md:px-8 md:pb-8 lg:hidden ${isActive ? 'opacity-100' : 'opacity-0'}`}
        >
          <div
            className={`mb-3 flex shrink-0 items-end transition-all delay-100 duration-500 ease-out md:mb-4 ${isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}
          >
            {item.logoPath ? (
              <img src={getLogoUrl(item.logoPath) || undefined} alt={item.title} className="max-h-12 max-w-[180px] object-contain md:max-h-16 md:max-w-[240px]" />
            ) : (
              <h2 className="text-xl font-bold text-white md:text-2xl">{item.title}</h2>
            )}
          </div>
          <p className={`mb-2 line-clamp-2 min-h-0 shrink text-xs text-white/80 transition-all delay-150 duration-500 ease-out md:mb-4 md:line-clamp-3 md:max-w-md md:text-sm ${isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
            {item.overview}
          </p>
          <div className={`shrink-0 transition-all delay-200 duration-500 ease-out ${isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
            {isMobile ? (
              <div className="flex items-center gap-2">
                <Button size="sm" className="h-7 min-w-0 flex-1 gap-1 rounded-full bg-[#E50914] px-2.5 text-xs font-semibold text-white hover:bg-[#ca0812]"
                  onClick={() => window.location.href = continueWatchingPath || playPath}>
                  <Play className="size-3.5 fill-current" />
                  {continueWatchingPath ? '继续观看' : playNowLabel}
                </Button>
              </div>
            ) : (
              <div className="flex flex-wrap gap-2 md:gap-3">
                {continueWatchingPath && (
                  <NavLink to={continueWatchingPath} className="group relative inline-flex h-8 rounded-full gap-1.5 bg-[#E50914] px-3 font-semibold text-white hover:bg-[#ca0812] md:h-9 md:gap-2 md:px-4 md:text-sm items-center">
                    <span className="inline-flex items-center gap-1.5 transition-opacity duration-200 group-hover:opacity-0 md:gap-2">
                      <Play className="size-3.5 fill-current md:size-4" />
                      继续观看{continueWatchingLabel ? <span className="hidden md:inline">· {continueWatchingLabel}</span> : null}
                    </span>
                    {continueWatchingProgressLabel && (
                      <span className="pointer-events-none absolute inset-0 hidden items-center justify-center text-[11px] font-semibold opacity-0 transition-opacity duration-200 group-hover:opacity-100 md:flex">
                        {continueWatchingProgressLabel}
                      </span>
                    )}
                  </NavLink>
                )}
                <NavLink to={playPath} className="inline-flex h-8 rounded-full gap-1.5 bg-white px-3 font-semibold text-black hover:bg-white/90 md:h-9 md:gap-2 md:px-4 md:text-sm items-center">
                  <Play className="size-3.5 fill-current md:size-4" />
                  {playNowLabel}
                </NavLink>
                <NavLink to={detailPath} className="inline-flex h-8 rounded-full gap-1.5 bg-white/30 px-3 font-semibold text-white hover:bg-white/40 md:h-9 md:gap-2 md:px-4 md:text-sm items-center">
                  <Info className="size-3.5 md:size-4" />
                  查看详情
                </NavLink>
              </div>
            )}
          </div>
        </div>

        {/* 遮罩层 - 桌面端 */}
        <div className={`absolute inset-0 hidden flex-col justify-end rounded-lg bg-gradient-to-r from-black/90 via-black/50 via-40% to-transparent px-16 pt-25 pb-16 transition-opacity duration-500 ease-out lg:flex ${isActive ? 'opacity-100' : 'opacity-0'}`}>
          <div className={`mb-8 flex h-35 items-end transition-all delay-100 duration-500 ease-out ${isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
            {item.logoPath ? (
              <img src={getLogoUrl(item.logoPath) || undefined} alt={item.title} className="max-h-35 max-w-md object-contain xl:max-h-40 xl:max-w-lg" />
            ) : (
              <h2 className="text-2xl font-bold text-white md:text-4xl lg:text-5xl">{item.title}</h2>
            )}
          </div>
          <p className={`mb-5 line-clamp-3 max-w-xl text-[0.7rem] text-white/80 transition-all delay-150 duration-500 ease-out md:max-w-2xl md:text-base ${isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
            {item.overview}
          </p>
          <div className={`flex gap-3 transition-all delay-200 duration-500 ease-out ${isActive ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
            {continueWatchingPath && (
              <NavLink to={continueWatchingPath} className="group relative inline-flex rounded-full gap-2 bg-[#E50914] font-semibold text-white hover:bg-[#ca0812] px-4 py-2 items-center">
                <span className="inline-flex items-center gap-2 transition-opacity duration-200 group-hover:opacity-0">
                  <Play className="size-5 fill-current" />
                  继续观看{continueWatchingLabel ? <span>· {continueWatchingLabel}</span> : null}
                </span>
                {continueWatchingProgressLabel && (
                  <span className="pointer-events-none absolute inset-0 hidden items-center justify-center text-xs font-semibold opacity-0 transition-opacity duration-200 group-hover:opacity-100 xl:flex">
                    {continueWatchingProgressLabel}
                  </span>
                )}
              </NavLink>
            )}
            <NavLink to={playPath} className="inline-flex rounded-full gap-2 bg-white font-semibold text-black hover:bg-white/90 px-4 py-2 items-center">
              <Play className="size-5 fill-current" />
              {playNowLabel}
            </NavLink>
            <NavLink to={detailPath} className="inline-flex rounded-full gap-2 bg-white/30 font-semibold text-white hover:bg-white/40 px-4 py-2 items-center">
              <Info className="size-5" />
              查看详情
            </NavLink>
          </div>
        </div>
      </AspectRatio>
    </CarouselItem>
  )
})

/**
 * FeaturedCarousel - 精选内容轮播图组件
 */
export const FeaturedCarousel = memo(function FeaturedCarousel({
  items,
  loading = false,
  autoplayDelay = 5000,
}: FeaturedCarouselProps) {
  const [api, setApi] = useState<CarouselApi>()
  const [activeIndex, setActiveIndex] = useState(0)
  // ponytail: 延迟轮播初始化，首屏先渲染静态图绕过 embla measure() 729ms 强制重排
  const [carouselReady, setCarouselReady] = useState(false)
  // 静态首屏文本淡入动画
  const [textVisible, setTextVisible] = useState(false)
  const miniApiRef = useRef<CarouselApi | null>(null)
  const isMobile = useIsMobile()
  const viewingHistory = useViewingHistoryStore(state => state.viewingHistory)

  useEffect(() => {
    const idle = 'requestIdleCallback' in window ? requestIdleCallback : (cb: () => void) => setTimeout(cb, 0)
    const id = idle(() => setCarouselReady(true))
    return () => {
      if ('cancelIdleCallback' in window) cancelIdleCallback(id as number)
      else clearTimeout(id as ReturnType<typeof setTimeout>)
    }
  }, [])

  // 触发静态首屏文本淡入（下一帧 kick-off CSS transition）
  useEffect(() => {
    if (carouselReady) return
    const raf = requestAnimationFrame(() => setTextVisible(true))
    return () => cancelAnimationFrame(raf)
  }, [carouselReady])

  // 缓存首张巨幕 URL 到 sessionStorage，下次访问 HTML 预加载跳过 React 渲染延迟
  useEffect(() => {
    if (items.length > 0) {
      const url = getBackdropUrl(items[0].backdropPath)
      if (url) {
        try { sessionStorage.setItem('lcp_backdrop', url) } catch (_) {}
      }
    }
  }, [items])

  const latestTmdbHistoryMap = useMemo(() => {
    const latestHistoryMap = new Map<string, ViewingHistoryItem>()
    const latestMappedHistoryMap = new Map<string, ViewingHistoryItem>()

    viewingHistory.forEach(historyItem => {
      if (!isTmdbHistoryItem(historyItem)) return

      const mediaKey = `${historyItem.tmdbMediaType}-${historyItem.tmdbId}`
      const latestHistory = latestHistoryMap.get(mediaKey)
      const latestMappedHistory = latestMappedHistoryMap.get(mediaKey)

      if (!latestHistory || historyItem.timestamp > latestHistory.timestamp) {
        latestHistoryMap.set(mediaKey, historyItem)
      }

      if (!historyItem.sourceCode || !historyItem.vodId) return

      if (!latestMappedHistory || historyItem.timestamp > latestMappedHistory.timestamp) {
        latestMappedHistoryMap.set(mediaKey, historyItem)
      }
    })

    const resultMap = new Map<string, ViewingHistoryItem>()
    latestHistoryMap.forEach((historyItem, mediaKey) => {
      resultMap.set(mediaKey, latestMappedHistoryMap.get(mediaKey) || historyItem)
    })
    return resultMap
  }, [viewingHistory])

  // 根据设备类型获取AspectRatio
  // 移动端: 4/3, 平板: 16/9, 桌面: 9/4
  const getAspectRatio = () => {
    if (isMobile) return 4 / 3
    if (window.innerWidth < 1024) return 16 / 9
    return 9 / 4
  }

  const MINI_PAGE_SIZE = 6

  // 监听 carousel 选择变化，按页滚动 mini 轮播
  useEffect(() => {
    if (!api) return

    const onSelect = () => {
      const idx = api.selectedScrollSnap()
      setActiveIndex(idx)
      const ma = miniApiRef.current
      if (ma) {
        const currentPage = Math.floor(idx / MINI_PAGE_SIZE)
        const miniIdx = currentPage * MINI_PAGE_SIZE
        const scrollSnap = ma.selectedScrollSnap()
        if (scrollSnap !== miniIdx) {
          ma.scrollTo(miniIdx)
        }
      }
    }

    onSelect()
    api.on('select', onSelect)
    return () => {
      api.off('select', onSelect)
    }
  }, [api])

  // 骨架屏
  if (loading) {
    return (
      <div>
        <AspectRatio ratio={getAspectRatio()} className="bg-muted overflow-hidden rounded-lg">
          <Skeleton className="h-full w-full rounded-lg" />
          {/* 骨架屏遮罩层 - 移动端/平板 */}
          <div className="absolute inset-0 flex min-h-0 flex-col justify-end rounded-lg bg-gradient-to-t from-black/90 via-black/50 via-60% to-transparent px-6 pt-4 pb-6 md:px-8 md:pb-8 lg:hidden">
            <Skeleton className="mb-3 h-8 w-36 md:mb-4 md:h-10 md:w-48" />
            <Skeleton className="mb-2 h-3 w-2/3 md:h-4" />
            <Skeleton className="mb-3 h-3 w-1/2 md:mb-4 md:h-4" />
            <div className="flex gap-2 md:gap-3">
              <Skeleton className="h-8 w-20 md:h-9 md:w-24" />
              <Skeleton className="h-8 w-20 md:h-9 md:w-24" />
            </div>
          </div>
          {/* 骨架屏遮罩层 - 桌面端 */}
          <div className="absolute inset-0 hidden flex-col justify-end rounded-lg bg-gradient-to-r from-black/90 via-black/50 via-40% to-transparent px-16 pt-25 pb-16 lg:flex">
            <Skeleton className="mb-8 h-20 w-80 xl:h-24 xl:w-96" />
            <Skeleton className="mb-2 h-4 w-2/3 max-w-2xl" />
            <Skeleton className="mb-5 h-4 w-1/2 max-w-xl" />
            <div className="flex gap-3">
              <Skeleton className="h-10 w-28" />
              <Skeleton className="h-10 w-28" />
            </div>
          </div>
        </AspectRatio>
      </div>
    )
  }

  if (items.length === 0) {
    return null
  }

  // 首屏静态渲染：绕过 embla measure() 强制重排，LCP 图片直接上屏
  // 视觉与 FeaturedCarouselItem 完全一致（含观看记录按钮逻辑），避免切换闪烁
  if (!carouselReady) {
    const first = items[0]
    const playPath = buildTmdbPlayPath(first.mediaType, first.id)
    const detailPath = buildTmdbDetailPath(first.mediaType, first.id)
    const latestTmdbHistory = latestTmdbHistoryMap.get(`${first.mediaType}-${first.id}`)
    const continueWatchingLabel = latestTmdbHistory
      ? latestTmdbHistory.episodeName || `第${latestTmdbHistory.episodeIndex + 1}集`
      : ''
    const continueWatchingProgressLabel = latestTmdbHistory
      ? latestTmdbHistory.duration > 0
        ? `已观看 ${Math.round(Math.min(100, Math.max(0, (latestTmdbHistory.playbackPosition / latestTmdbHistory.duration) * 100)))}%`
        : '已开始观看'
      : ''
    const continueWatchingPath = latestTmdbHistory
      ? latestTmdbHistory.sourceCode && latestTmdbHistory.vodId
        ? buildHistoryPlayPath(latestTmdbHistory)
        : buildTmdbPlayPath(first.mediaType, first.id, {
            episodeIndex: latestTmdbHistory.episodeIndex,
            seasonNumber: first.mediaType === 'tv' ? latestTmdbHistory.tmdbSeasonNumber ?? undefined : undefined,
          })
      : ''
    const playNowLabel = continueWatchingPath ? '从头播放' : '立即播放'

    return (
      <div className="relative">
        <div className="min-w-0 shrink-0 grow-0 basis-full h-fit rounded-lg">
          <AspectRatio ratio={getAspectRatio()} className="bg-muted overflow-hidden rounded-lg">
            <img
              className="h-full w-full rounded-lg object-cover object-center md:object-top-right"
              src={getBackdropUrl(first.backdropPath) || undefined}
              alt={first.title}
              fetchPriority="high"
              style={{ contentVisibility: 'visible' }}
            />
            {/* 移动端/平板遮罩 — 与 FeaturedCarouselItem 完全一致 */}
            <div className="absolute inset-0 flex min-h-0 flex-col justify-end rounded-lg bg-gradient-to-t from-black/90 via-black/50 via-60% to-transparent px-6 pt-4 pb-6 transition-opacity duration-500 ease-out md:px-8 md:pb-8 lg:hidden">
              <div className={`mb-3 flex shrink-0 items-end transition-all delay-100 duration-500 ease-out md:mb-4 ${textVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
                {first.logoPath ? (
                  <img src={getLogoUrl(first.logoPath) || undefined} alt={first.title} className="max-h-12 max-w-[180px] object-contain md:max-h-16 md:max-w-[240px]" />
                ) : (
                  <h2 className="text-xl font-bold text-white md:text-2xl">{first.title}</h2>
                )}
              </div>
              <p className={`mb-2 line-clamp-2 min-h-0 shrink text-xs text-white/80 transition-all delay-150 duration-500 ease-out md:mb-4 md:line-clamp-3 md:max-w-md md:text-sm ${textVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
                {first.overview}
              </p>
              <div className={`shrink-0 transition-all delay-200 duration-500 ease-out ${textVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
                {isMobile ? (
                  <div className="flex items-center gap-2">
                    <Button size="sm" className="h-7 min-w-0 flex-1 gap-1 rounded-full bg-[#E50914] px-2.5 text-xs font-semibold text-white hover:bg-[#ca0812]"
                      onClick={() => window.location.href = continueWatchingPath || playPath}>
                      <Play className="size-3.5 fill-current" />
                      {continueWatchingPath ? '继续观看' : playNowLabel}
                    </Button>
                  </div>
                ) : (
                  <div className="flex flex-wrap gap-2 md:gap-3">
                    {continueWatchingPath && (
                      <NavLink to={continueWatchingPath} className="group relative inline-flex h-8 rounded-full gap-1.5 bg-[#E50914] px-3 font-semibold text-white hover:bg-[#ca0812] md:h-9 md:gap-2 md:px-4 md:text-sm items-center">
                        <span className="inline-flex items-center gap-1.5 transition-opacity duration-200 group-hover:opacity-0 md:gap-2">
                          <Play className="size-3.5 fill-current md:size-4" />
                          继续观看{continueWatchingLabel ? <span className="hidden md:inline">· {continueWatchingLabel}</span> : null}
                        </span>
                        {continueWatchingProgressLabel && (
                          <span className="pointer-events-none absolute inset-0 hidden items-center justify-center text-[11px] font-semibold opacity-0 transition-opacity duration-200 group-hover:opacity-100 md:flex">
                            {continueWatchingProgressLabel}
                          </span>
                        )}
                      </NavLink>
                    )}
                    <NavLink to={playPath} className="inline-flex h-8 rounded-full gap-1.5 bg-white px-3 font-semibold text-black hover:bg-white/90 md:h-9 md:gap-2 md:px-4 md:text-sm items-center">
                      <Play className="size-3.5 fill-current md:size-4" />
                      {playNowLabel}
                    </NavLink>
                    <NavLink to={detailPath} className="inline-flex h-8 rounded-full gap-1.5 bg-white/30 px-3 font-semibold text-white hover:bg-white/40 md:h-9 md:gap-2 md:px-4 md:text-sm items-center">
                      <Info className="size-3.5 md:size-4" />
                      查看详情
                    </NavLink>
                  </div>
                )}
              </div>
            </div>
            {/* 桌面端遮罩 — 与 FeaturedCarouselItem 完全一致 */}
            <div className="absolute inset-0 hidden flex-col justify-end rounded-lg bg-gradient-to-r from-black/90 via-black/50 via-40% to-transparent px-16 pt-25 pb-16 transition-opacity duration-500 ease-out lg:flex">
              <div className={`mb-8 flex h-35 items-end transition-all delay-100 duration-500 ease-out ${textVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
                {first.logoPath ? (
                  <img src={getLogoUrl(first.logoPath) || undefined} alt={first.title} className="max-h-35 max-w-md object-contain xl:max-h-40 xl:max-w-lg" />
                ) : (
                  <h2 className="text-2xl font-bold text-white md:text-4xl lg:text-5xl">{first.title}</h2>
                )}
              </div>
              <p className={`mb-5 line-clamp-3 max-w-xl text-[0.7rem] text-white/80 transition-all delay-150 duration-500 ease-out md:max-w-2xl md:text-base ${textVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
                {first.overview}
              </p>
              <div className={`flex gap-3 transition-all delay-200 duration-500 ease-out ${textVisible ? 'translate-y-0 opacity-100' : 'translate-y-4 opacity-0'}`}>
                {continueWatchingPath && (
                  <NavLink to={continueWatchingPath} className="group relative inline-flex rounded-full gap-2 bg-[#E50914] font-semibold text-white hover:bg-[#ca0812] px-4 py-2 items-center">
                    <span className="inline-flex items-center gap-2 transition-opacity duration-200 group-hover:opacity-0">
                      <Play className="size-5 fill-current" />
                      继续观看{continueWatchingLabel ? <span>· {continueWatchingLabel}</span> : null}
                    </span>
                    {continueWatchingProgressLabel && (
                      <span className="pointer-events-none absolute inset-0 hidden items-center justify-center text-xs font-semibold opacity-0 transition-opacity duration-200 group-hover:opacity-100 xl:flex">
                        {continueWatchingProgressLabel}
                      </span>
                    )}
                  </NavLink>
                )}
                <NavLink to={playPath} className="inline-flex rounded-full gap-2 bg-white font-semibold text-black hover:bg-white/90 px-4 py-2 items-center">
                  <Play className="size-5 fill-current" />
                  {playNowLabel}
                </NavLink>
                <NavLink to={detailPath} className="inline-flex rounded-full gap-2 bg-white/30 font-semibold text-white hover:bg-white/40 px-4 py-2 items-center">
                  <Info className="size-5" />
                  查看详情
                </NavLink>
              </div>
            </div>
          </AspectRatio>
        </div>
      </div>
    )
  }

  return (
    <div className="relative">
      <Carousel
        className="h-fit rounded-lg"
        opts={{
          align: 'center',
          loop: true,
        }}
        plugins={[
          Autoplay({
            delay: autoplayDelay,
            stopOnInteraction: true,
            stopOnMouseEnter: true,
          }),
        ]}
        setApi={setApi}
      >
        <CarouselContent>
          {items.map((item, index) => (
            <FeaturedCarouselItem
              key={`${item.mediaType}-${item.id}`}
              item={item}
              isActive={index === activeIndex}
              getAspectRatio={getAspectRatio}
              isMobile={isMobile}
              latestTmdbHistoryMap={latestTmdbHistoryMap}
            />
          ))}
        </CarouselContent>
      </Carousel>
    </div>
  )
})

import { useCallback, useEffect, useMemo, useRef, useState, useDeferredValue } from 'react'
import type {
  SearchProgressEvent,
  SearchResultEvent,
  SearchStartEvent,
  VideoItem,
  VideoSource,
} from '@ouonnki/cms-core'
import type { TmdbMediaType } from '@/shared/types/tmdb'
import { useCmsClient } from '@/shared/hooks'
import { useApiStore } from '@/shared/store/apiStore'
import { useSettingStore } from '@/shared/store/settingStore'
import { useTmdbMatchCacheStore } from '@/shared/store/tmdbMatchCacheStore'
import {
  buildPlaylistMatches,
  isEnglishText,
  type PlaylistMatchItem,
  type SeasonSourceMatches,
  type SourceBestMatch,
} from './playlistMatcher'
import type { DetailSeason } from './types'
import { COUNTRY_CHINESE_NAMES } from '@/shared/constants/countries'

interface UsePlaylistMatchesParams {
  active: boolean
  tmdbType: TmdbMediaType
  tmdbId: number
  title: string
  alternativeTitles?: string[]
  releaseDate?: string
  seasons: DetailSeason[]
  originCountry?: string[]
  genres?: Array<{ id: number; name: string }>
}

export interface PlaylistMatchesProgress {
  phase: 'idle' | 'search' | 'match' | 'complete'
  completed: number
  total: number
  currentSourceName: string
  currentSourceId: string
  lastEvent: 'idle' | 'start' | 'progress' | 'result' | 'complete'
  lastEventAt: number | null
  lastResultSourceName: string
  lastResultSourceId: string
  lastResultCount: number
}

interface PlaylistMatchesState {
  loading: boolean
  error: string | null
  searched: boolean
  searchedKeyword: string
  progress: PlaylistMatchesProgress
  startedAt: number | null
  completedAt: number | null
  candidates: PlaylistMatchItem[]
  movieSourceMatches: SourceBestMatch[]
  seasonSourceMatches: SeasonSourceMatches[]
}

const initialState: PlaylistMatchesState = {
  loading: false,
  error: null,
  searched: false,
  searchedKeyword: '',
  progress: {
    phase: 'idle',
    completed: 0,
    total: 0,
    currentSourceName: '',
    currentSourceId: '',
    lastEvent: 'idle',
    lastEventAt: null,
    lastResultSourceName: '',
    lastResultSourceId: '',
    lastResultCount: 0,
  },
  startedAt: null,
  completedAt: null,
  candidates: [],
  movieSourceMatches: [],
  seasonSourceMatches: [],
}

const TMDB_MATCH_CACHE_MAX_ENTRIES = 200

const normalizeCacheText = (value: string) => value.trim().toLowerCase().replace(/\s+/g, ' ')

const buildSourceSignature = (sources: VideoSource[]) =>
  sources
    .slice()
    .sort((a, b) => a.id.localeCompare(b.id))
    .map(source => {
      const updatedAt =
        source.updatedAt instanceof Date
          ? source.updatedAt.getTime()
          : source.updatedAt
            ? new Date(source.updatedAt).getTime()
            : 0
      return [
        source.id,
        source.url || '',
        source.detailUrl || '',
        source.timeout ?? '',
        source.retry ?? '',
        Number.isFinite(updatedAt) ? updatedAt : 0,
      ].join('|')
    })
    .join(';;')

export function usePlaylistMatches({
  active,
  tmdbType,
  tmdbId,
  title,
  alternativeTitles,
  releaseDate,
  seasons,
  originCountry,
  genres,
}: UsePlaylistMatchesParams) {
  const cmsClient = useCmsClient()
  const videoAPIs = useApiStore(state => state.videoAPIs)
  const tmdbMatchCacheTTLHours = useSettingStore(state => state.playback.tmdbMatchCacheTTLHours)
  const getTmdbMatchCacheEntry = useTmdbMatchCacheStore(state => state.getEntry)
  const setTmdbMatchCacheEntry = useTmdbMatchCacheStore(state => state.setEntry)
  const pruneTmdbMatchCache = useTmdbMatchCacheStore(state => state.prune)
  const enabledSources = useMemo(() => videoAPIs.filter(source => source.isEnabled), [videoAPIs])

  const [state, setState] = useState<PlaylistMatchesState>(initialState)
  const abortRef = useRef<AbortController | null>(null)
  const searchKeyRef = useRef('')
  const sessionRef = useRef<{
    token: string
    keyword: string
    sourceIdSet: Set<string>
  } | null>(null)
  const uniqueMapRef = useRef<Map<string, VideoItem>>(new Map())
  const recomputeTimerRef = useRef<number | null>(null)
  const unsubRef = useRef<Array<() => void>>([])
  // Track accumulated item count to trigger deferred fuse computation
  const [accumulatedVersion, setAccumulatedVersion] = useState(0)
  const deferredAccumulatedVersion = useDeferredValue(accumulatedVersion)
  const isFuseStale = accumulatedVersion !== deferredAccumulatedVersion
  const isFuseStaleRef = useRef(false)
  isFuseStaleRef.current = isFuseStale

  const clearRecomputeTimer = useCallback(() => {
    if (!recomputeTimerRef.current) return
    window.clearTimeout(recomputeTimerRef.current)
    recomputeTimerRef.current = null
  }, [])

  const clearSubscriptions = useCallback(() => {
    unsubRef.current.forEach(unsub => unsub())
    unsubRef.current = []
  }, [])

  const scheduleRecompute = useCallback(
    (params: {
      keyword: string
      releaseYear?: string
      sourceMetaList: Array<{ id: string; name: string }>
    }) => {
      clearRecomputeTimer()

      recomputeTimerRef.current = window.setTimeout(() => {
        if (isFuseStaleRef.current) {
          // Items are still being accumulated (deferred value hasn't caught up),
          // reschedule to avoid blocking the main thread with CPU-intensive Fuse matching
          scheduleRecompute(params)
          return
        }
        const items = Array.from(uniqueMapRef.current.values())
        const { candidates, movieSourceMatches, seasonSourceMatches } = buildPlaylistMatches({
          mediaType: tmdbType,
          items,
          title: params.keyword,
          alternativeTitles,
          releaseYear: params.releaseYear,
          seasons,
          sources: params.sourceMetaList,
        })

        setState(prev => ({
          ...prev,
          candidates,
          movieSourceMatches,
          seasonSourceMatches,
        }))
      }, 160)
    },
    [clearRecomputeTimer, alternativeTitles, seasons, tmdbType],
  )

  const runSearch = useCallback(
    async (force = false) => {
      const keyword = title.trim()
      const releaseYear = releaseDate ? releaseDate.slice(0, 4) : undefined
      const area = originCountry?.[0] ? COUNTRY_CHINESE_NAMES[originCountry[0]] : undefined
      const classParams = genres?.map(g => g.name).filter(Boolean)
      const normalizedKeyword = normalizeCacheText(keyword)
      const sourceSignature = buildSourceSignature(enabledSources)
      const currentKey = [
        tmdbType,
        tmdbId,
        normalizedKeyword,
        releaseYear || '',
        sourceSignature,
      ].join('::')

      if (!keyword) {
        setState(prev => ({
          ...prev,
          loading: false,
          searched: true,
          error: '当前条目缺少标题，无法搜索播放资源',
        }))
        return
      }

      if (enabledSources.length === 0) {
        setState(prev => ({
          ...prev,
          loading: false,
          searched: true,
          searchedKeyword: keyword,
          error: '当前没有启用的 CMS 视频源，请先到设置中启用视频源',
          progress: {
            phase: 'idle',
            completed: 0,
            total: 0,
            currentSourceName: '',
            currentSourceId: '',
            lastEvent: 'idle',
            lastEventAt: null,
            lastResultSourceName: '',
            lastResultSourceId: '',
            lastResultCount: 0,
          },
          startedAt: null,
          completedAt: null,
          candidates: [],
          movieSourceMatches: [],
          seasonSourceMatches: [],
        }))
        return
      }

      if (!force && searchKeyRef.current === currentKey && state.searched) {
        return
      }

      if (!force) {
        const cachedEntry = getTmdbMatchCacheEntry(currentKey, tmdbMatchCacheTTLHours)
        if (cachedEntry) {
          abortRef.current?.abort()
          clearSubscriptions()
          clearRecomputeTimer()
          searchKeyRef.current = currentKey
          setState(prev => ({
            ...prev,
            loading: false,
            error: null,
            searched: true,
            searchedKeyword: cachedEntry.payload.searchedKeyword,
            progress: {
              phase: 'complete',
              completed: 0,
              total: 0,
              currentSourceName: '',
              currentSourceId: '',
              lastEvent: 'complete',
              lastEventAt: Date.now(),
              lastResultSourceName: '',
              lastResultSourceId: '',
              lastResultCount: 0,
            },
            startedAt: null,
            completedAt: null,
            candidates: cachedEntry.payload.candidates,
            movieSourceMatches: cachedEntry.payload.movieSourceMatches,
            seasonSourceMatches: cachedEntry.payload.seasonSourceMatches,
          }))
          return
        }
      }

      abortRef.current?.abort()
      const controller = new AbortController()
      abortRef.current = controller
      searchKeyRef.current = currentKey

      clearSubscriptions()
      uniqueMapRef.current = new Map()
      setAccumulatedVersion(0)

      const sourceMetaList = enabledSources.map(source => ({
        id: source.id,
        name: source.name || source.id || '未知源',
      }))
      const sessionToken = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`

      sessionRef.current = {
        token: sessionToken,
        keyword,
        sourceIdSet: new Set(sourceMetaList.map(source => source.id)),
      }

      setState(prev => ({
        ...prev,
        loading: true,
        error: null,
        searched: true,
        searchedKeyword: keyword,
        startedAt: Date.now(),
        completedAt: null,
        progress: {
          phase: 'search',
          completed: 0,
          total: enabledSources.length,
          currentSourceName: '',
          currentSourceId: '',
          lastEvent: 'start',
          lastEventAt: Date.now(),
          lastResultSourceName: '',
          lastResultSourceId: '',
          lastResultCount: 0,
        },
        candidates: [],
        movieSourceMatches: [],
        seasonSourceMatches: [],
      }))

      try {
        const isSameSources = (sources: VideoSource[]) => {
          const session = sessionRef.current
          if (!session) return false
          if (sources.length !== session.sourceIdSet.size) return false
          return sources.every(source => session.sourceIdSet.has(source.id))
        }

        const onStart = (event: SearchStartEvent) => {
          const session = sessionRef.current
          if (!session || session.token !== sessionToken) return
          if (event.query !== session.keyword) return
          if (!isSameSources(event.sources)) return

          setState(prev => ({
            ...prev,
            progress: {
              ...prev.progress,
              phase: 'search',
              lastEvent: 'start',
              lastEventAt: Date.now(),
            },
          }))
        }

        const onProgress = (event: SearchProgressEvent) => {
          const session = sessionRef.current
          if (!session || session.token !== sessionToken) return
          if (!session.sourceIdSet.has(event.source.id)) return

          setState(prev => ({
            ...prev,
            progress: {
              phase: 'search',
              completed: event.completed,
              total: event.total,
              currentSourceName: event.source.name || event.source.id || '未知源',
              currentSourceId: event.source.id,
              lastEvent: 'progress',
              lastEventAt: Date.now(),
              lastResultSourceName: prev.progress.lastResultSourceName,
              lastResultSourceId: prev.progress.lastResultSourceId,
              lastResultCount: prev.progress.lastResultCount,
            },
          }))
        }

        const onResult = (event: SearchResultEvent) => {
          const session = sessionRef.current
          if (!session || session.token !== sessionToken) return
          if (!session.sourceIdSet.has(event.source.id)) return

          setState(prev => ({
            ...prev,
            progress: {
              ...prev.progress,
              phase: 'match',
              lastEvent: 'result',
              lastEventAt: Date.now(),
              lastResultSourceName: event.source.name || event.source.id || '未知源',
              lastResultSourceId: event.source.id,
              lastResultCount: event.items.length,
            },
          }))

          let hasNewItems = false
          event.items.forEach(item => {
            const key = `${item.source_code || 'unknown'}::${item.vod_id}`
            if (!uniqueMapRef.current.has(key)) {
              uniqueMapRef.current.set(key, item)
              hasNewItems = true
            }
          })

          if (hasNewItems) {
            setAccumulatedVersion(v => v + 1)
          }

          scheduleRecompute({ keyword, releaseYear, sourceMetaList })
        }

        const onComplete = () => {
          const session = sessionRef.current
          if (!session || session.token !== sessionToken) return

          setState(prev => ({
            ...prev,
            progress: {
              ...prev.progress,
              phase: 'match',
              lastEvent: 'complete',
              lastEventAt: Date.now(),
            },
          }))
          scheduleRecompute({ keyword, releaseYear, sourceMetaList })
        }

        unsubRef.current = [
          cmsClient.on('search:start', onStart),
          cmsClient.on('search:progress', onProgress),
          cmsClient.on('search:result', onResult),
          cmsClient.on('search:complete', onComplete),
        ]

        // 搜索策略
        const needsFallbackSearch = async () => {
          const items = Array.from(uniqueMapRef.current.values())
          if (items.length === 0) return true

          const { movieSourceMatches, seasonSourceMatches } = buildPlaylistMatches({
            mediaType: tmdbType,
            items,
            title: keyword,
            alternativeTitles,
            releaseYear,
            seasons,
            sources: sourceMetaList,
          })

          const allMatches = movieSourceMatches.length > 0
            ? movieSourceMatches
            : seasonSourceMatches.length > 0
              ? seasonSourceMatches.flatMap(s => s.sourceMatches)
              : []

          const bestScore = allMatches.length > 0
            ? Math.max(...allMatches.map(m => m.bestMatch?.score ?? 0))
            : 0

          const lowScoreCount = allMatches.filter(m => (m.bestMatch?.score ?? 0) < 80).length
          return bestScore < 85 || lowScoreCount > allMatches.length / 2
        }

        // 回退关键词：译名（去重）
        const fallbackKeywords = [
          ...new Set((alternativeTitles || []).filter((v): v is string => !!v?.trim())),
        ]

        const isTitleEnglish = isEnglishText(keyword)
        let fallbackAttempted = false

        if (keyword.length < 2 && fallbackKeywords.length > 0) {
          // 短标题：直接用回退关键词搜索
          fallbackAttempted = true
          await Promise.all(
            fallbackKeywords.map(altKwd =>
              cmsClient.aggregatedSearch(altKwd, enabledSources, 1, controller.signal, area, classParams).catch(() => {}),
            ),
          )
        } else if (isTitleEnglish && fallbackKeywords.length > 0) {
          // 主标题为全英文：并发搜索 title + 所有别名，不等回退
          fallbackAttempted = true
          await Promise.all([
            cmsClient.aggregatedSearch(keyword, enabledSources, 1, controller.signal, area, classParams).catch(() => {}),
            ...fallbackKeywords.map(altKwd =>
              cmsClient.aggregatedSearch(altKwd, enabledSources, 1, controller.signal, area, classParams).catch(() => {}),
            ),
          ])
        } else {
          // 先用 title 搜索
          await cmsClient.aggregatedSearch(keyword, enabledSources, 1, controller.signal, area, classParams)

          // 评分低则用回退关键词搜索
          if (await needsFallbackSearch()) {
            fallbackAttempted = true
            await Promise.all(
              fallbackKeywords.map(altKwd =>
                cmsClient.aggregatedSearch(altKwd, enabledSources, 1, controller.signal, area, classParams).catch(() => {}),
              ),
            )
          }
        }

        const items = Array.from(uniqueMapRef.current.values())
        const { candidates, movieSourceMatches, seasonSourceMatches } = buildPlaylistMatches({
          mediaType: tmdbType,
          items,
          title: keyword,
          alternativeTitles,
          releaseYear,
          seasons,
          sources: sourceMetaList,
          strictScore: fallbackAttempted,
        })

        setState(prev => ({
          ...prev,
          loading: false,
          error: null,
          progress: { ...prev.progress, phase: 'complete', lastEvent: 'complete', lastEventAt: Date.now() },
          completedAt: Date.now(),
          candidates,
          movieSourceMatches,
          seasonSourceMatches,
        }))

        setTmdbMatchCacheEntry(currentKey, {
          searchedKeyword: keyword,
          candidates,
          movieSourceMatches,
          seasonSourceMatches,
        })
        pruneTmdbMatchCache(TMDB_MATCH_CACHE_MAX_ENTRIES)
      } catch (error) {
        if ((error as Error).name === 'AbortError') {
          return
        }

        setState(prev => ({
          ...prev,
          loading: false,
          error: (error as Error).message || '搜索 CMS 资源失败',
          progress: {
            phase: 'idle',
            completed: 0,
            total: 0,
            currentSourceName: '',
            currentSourceId: '',
            lastEvent: 'idle',
            lastEventAt: null,
            lastResultSourceName: '',
            lastResultSourceId: '',
            lastResultCount: 0,
          },
          startedAt: null,
          completedAt: null,
          candidates: [],
          movieSourceMatches: [],
          seasonSourceMatches: [],
        }))
      } finally {
        clearSubscriptions()
      }
    },
    [
      clearSubscriptions,
      cmsClient,
      enabledSources,
      getTmdbMatchCacheEntry,
      alternativeTitles,
      pruneTmdbMatchCache,
      releaseDate,
      seasons,
      scheduleRecompute,
      setTmdbMatchCacheEntry,
      state.searched,
      title,
      tmdbMatchCacheTTLHours,
      tmdbId,
      tmdbType,
      clearRecomputeTimer,
    ],
  )

  useEffect(() => {
    if (!active) return
    runSearch(false)
  }, [active, runSearch])

  useEffect(() => {
    return () => {
      abortRef.current?.abort()
      clearSubscriptions()
      clearRecomputeTimer()
    }
  }, [clearRecomputeTimer, clearSubscriptions])

  return {
    ...state,
    retry: () => runSearch(true),
  }
}

import { useEffect, useMemo, useState } from 'react'
import { useNavigate, useParams } from 'react-router'
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { ExternalLink, Heart, HeartOff } from 'lucide-react'
import { useDocumentTitle } from '@/shared/hooks'
import { useTmdbEnabled } from '@/shared/hooks/useTmdbMode'
import { useTmdbDetail } from '@/shared/hooks/useTmdb'
import { buildTmdbPlayPath } from '@/shared/lib/routes'
import { buildHistoryPlayPath, isTmdbHistoryItem } from '@/shared/lib/viewingHistory'
import type {
  TmdbMediaItem,
  TmdbMediaType,
  TmdbMovieDetail,
  TmdbTvDetail,
} from '@/shared/types/tmdb'
import { useFavoritesStore } from '@/features/favorites/store/favoritesStore'
import PlayerResourcesTab from '@/features/player/components/PlayerResourcesTab'
import { useSettingStore } from '@/shared/store/settingStore'
import { useGlobalContextMenuStore } from '@/shared/store/contextMenuStore'
import { useViewingHistoryStore } from '@/shared/store/viewingHistoryStore'
import { UnderlineTabs } from '@/shared/components/common'
import {
  DetailCastTab,
  DetailCollectionTab,
  DetailHeroSection,
  DetailLoadingSkeleton,
  DetailOverviewTab,
  DetailPlaylistTab,
  DetailStatePanel,
  DetailProductionTab,
  DetailSeasonsTab,
  type DetailCast,
  type DetailInfoField,
  type DetailTab,
  type TmdbRichDetail,
  extractRecommendations,
  extractTranslationTitles,
  augmentSeasonsFromTitles,
  formatCurrencyUSD,
  formatLargeNumber,
  formatRuntime,
  getReleaseYear,
  getCertShort,
  getCertFull,
  isAdultCert,
  mapBooleanLabel,
  mapCountryCodeToName,
  mapLanguageCodeToName,
  mapTvTypeLabel,
  pickHeroLogo,
  usePlaylistMatches,
} from '@/features/media/components'

const isSupportedMediaType = (value: string): value is TmdbMediaType => value === 'movie' || value === 'tv'
const TMDB_SEARCH_PATH = '/search?mode=tmdb'

export default function TmdbDetailView() {
  const navigate = useNavigate()
  const tmdbEnabled = useTmdbEnabled()
  const { type = '', tmdbId = '' } = useParams<{ type: string; tmdbId: string }>()

  // TMDB 未启用时重定向到首页
  useEffect(() => {
    if (!tmdbEnabled) {
      navigate('/', { replace: true })
    }
  }, [tmdbEnabled, navigate])

  const mediaType = isSupportedMediaType(type) ? type : null
  const parsedTmdbId = Number(tmdbId)
  const isValidId = Number.isInteger(parsedTmdbId) && parsedTmdbId > 0
  const isValidRoute = Boolean(mediaType) && isValidId

  const favorited = useFavoritesStore(state =>
    mediaType && isValidId ? state.isTmdbFavorited(parsedTmdbId, mediaType) : false,
  )
  const toggleTmdbFavorite = useFavoritesStore(state => state.toggleTmdbFavorite)
  const viewingHistory = useViewingHistoryStore(state => state.viewingHistory)

  const isAdultFilterEnabled = useSettingStore(state => state.system.isAdultFilterEnabled)

  const { detail, loading, error } = useTmdbDetail<TmdbMovieDetail | TmdbTvDetail>(
    isValidRoute ? parsedTmdbId : undefined,
    (mediaType || 'movie') as TmdbMediaType,
  )
  const tmdbType = (mediaType || 'movie') as TmdbMediaType
  const reducedMotion = useReducedMotion()

  const [activeTab, setActiveTab] = useState<DetailTab>('overview')

  const rawGenres = (detail as { genres?: Array<{ id: number; name: string }> } | null)?.genres || []
  const isAnime = rawGenres.some(g => g.id === 16)

  const tabItems: Array<{ key: DetailTab; label: string }> = [
    { key: 'overview', label: '概览' },
    { key: 'playlist', label: '播放列表' },
    { key: 'production', label: '制作与发行' },
    { key: 'cast', label: isAnime ? '声优' : '演员' },
    ...(mediaType === 'tv' ? [{ key: 'seasons' as const, label: '季信息' }] : []),
    ...(mediaType === 'movie' && (detail as TmdbRichDetail | null)?.belongs_to_collection?.id
      ? [{ key: 'collection' as const, label: '系列作品' }]
      : []),
    { key: 'resources', label: '网盘资源' },
  ]

  useDocumentTitle(detail?.title || '媒体详情')

  useEffect(() => {
    if (mediaType !== 'tv' && activeTab === 'seasons') {
      setActiveTab('overview')
    }
    if (mediaType !== 'movie' && activeTab === 'collection') {
      setActiveTab('overview')
    }
  }, [activeTab, mediaType])

  const safeRichDetail = detail as TmdbRichDetail | undefined

  const translationEntries = useMemo(() => {
    if (!detail) return []
    return extractTranslationTitles(safeRichDetail?.alternative_titles, [detail.title, detail.originalTitle])
  }, [detail, safeRichDetail?.alternative_titles])

  const alternativeTitles = useMemo(
    () => translationEntries.map(entry => entry.title),
    [translationEntries],
  )

  const safeSeasons = useMemo(() => {
    if (!safeRichDetail?.seasons) return []
    return augmentSeasonsFromTitles(safeRichDetail.seasons, alternativeTitles)
  }, [safeRichDetail?.seasons, alternativeTitles])

  const translationFields: DetailInfoField[] = useMemo(
    () =>
      translationEntries.map(entry => ({
        label: entry.countryName,
        value: entry.title,
      })),
    [translationEntries],
  )

  const playlistMatches = usePlaylistMatches({
    active: activeTab === 'playlist' && Boolean(detail) && isValidRoute,
    tmdbType,
    tmdbId: parsedTmdbId,
    title: detail?.title || '',
    alternativeTitles,
    releaseDate: detail?.releaseDate || '',
    seasons: safeSeasons,
    originCountry: detail?.originCountry,
    genres: rawGenres,
  })

  const latestTmdbHistory = useMemo(() => {
    if (!mediaType || !isValidRoute) return null

    const matchedItems = viewingHistory
      .filter(
      item =>
        isTmdbHistoryItem(item) &&
        item.tmdbMediaType === mediaType &&
        item.tmdbId === parsedTmdbId,
      )
      .sort((a, b) => b.timestamp - a.timestamp)
    if (matchedItems.length === 0) return null

    // 继续观看路径优先级：
    // 1. 优先选择带有 sourceCode + vodId 的记录（可直接回到上次源）
    // 2. 其次使用最近一条 tmdb 记录（回到同集/同季）
    return matchedItems.find(item => Boolean(item.sourceCode && item.vodId)) || matchedItems[0]
  }, [isValidRoute, mediaType, parsedTmdbId, viewingHistory])

  // 必须在所有提前 return 之前定义，保持 hooks 顺序一致
  const mediaSnapshot: TmdbMediaItem = detail
    ? {
        id: detail.id,
        mediaType: tmdbType,
        title: detail.title,
        originalTitle: detail.originalTitle,
        overview: detail.overview,
        posterPath: detail.posterPath,
        backdropPath: detail.backdropPath,
        logoPath: null,
        releaseDate: detail.releaseDate,
        voteAverage: detail.voteAverage,
        voteCount: detail.voteCount,
        popularity: detail.popularity,
        genreIds: detail.genreIds,
        originalLanguage: detail.originalLanguage,
        originCountry: detail.originCountry,
      }
    : (null as unknown as TmdbMediaItem)

  useEffect(() => {
    const items = []

    const homepage = (detail as TmdbRichDetail | null)?.homepage
    if (homepage) {
      items.push({
        id: 'detail-official-page',
        label: '官方页面',
        icon: <ExternalLink className="size-4" />,
        onClick: () => window.open(homepage, '_blank', 'noopener,noreferrer'),
      })
    }

    items.push({
      id: 'detail-toggle-favorite',
      label: favorited ? '取消收藏' : '加入收藏',
      icon: favorited ? <HeartOff className="size-4" /> : <Heart className="size-4" />,
      variant: favorited ? 'destructive' as const : 'default' as const,
      onClick: () => detail && toggleTmdbFavorite(mediaSnapshot),
    })

    const store = useGlobalContextMenuStore.getState()
    store.unregisterItems('detail-official-page', 'detail-toggle-favorite')
    const ids = store.registerItems(items)

    return () => {
      useGlobalContextMenuStore.getState().unregisterItems(...ids)
    }
  }, [(detail as TmdbRichDetail | null)?.homepage, favorited])

  if (!isValidRoute) {
    return (
        <DetailStatePanel
          mode="error"
          tag="路由校验失败"
          title="这个详情页地址不可用"
          description="当前链接缺少有效媒体类型或 ID，无法加载影视详情。"
          primaryAction={{
            label: '返回搜索页',
            onClick: () => navigate(TMDB_SEARCH_PATH),
          }}
          secondaryAction={{
            label: '回到上一页',
            onClick: () => navigate(-1),
          }}
        />
    )
  }

  if (!detail && loading) {
    return <DetailLoadingSkeleton />
  }

  if (error || !detail) {
    return (
        <DetailStatePanel
          mode="error"
          tag="详情加载失败"
          title="找不到影视详情"
          description={error || '该条目可能已下线，或当前服务暂不可用。'}
          primaryAction={{
            label: '返回搜索页',
            onClick: () => navigate(TMDB_SEARCH_PATH),
          }}
          secondaryAction={{
            label: '回到上一页',
            onClick: () => navigate(-1),
          }}
        />
    )
  }

  const richDetail = detail as TmdbRichDetail

  const releaseYear = getReleaseYear(detail.releaseDate)
  const heroLogo = pickHeroLogo(richDetail.images?.logos || [])
  const certShort = getCertShort(richDetail.adult, richDetail.release_dates, richDetail.content_ratings)
  const certFull = getCertFull(richDetail.adult, richDetail.release_dates, richDetail.content_ratings)

  if (isAdultFilterEnabled && isAdultCert(certShort)) {
    return (
        <DetailStatePanel
          mode="error"
          title="访问被拒绝"
          description={certFull || `分级 ${certShort}`}
          primaryAction={{
            label: '返回搜索页',
            onClick: () => navigate(TMDB_SEARCH_PATH),
          }}
          secondaryAction={{
            label: '回到上一页',
            onClick: () => navigate(-1),
          }}
        />
    )
  }

  const runtimeLabel =
    tmdbType === 'movie'
      ? formatRuntime(richDetail.runtime || 0)
      : (richDetail.episode_run_time?.[0] || 0) > 0
        ? `单集约${richDetail.episode_run_time?.[0] || 0}分钟`
        : ''

  const castList: DetailCast[] = (() => {
    if (tmdbType === 'tv' && richDetail.aggregate_credits?.cast) {
      return richDetail.aggregate_credits.cast.map(c => ({
        id: c.id,
        name: c.name,
        character: (c.roles || []).map(r => r.character).join(' / ') || undefined,
        order: Number.MAX_SAFE_INTEGER - (c.total_episode_count || 0),
        profile_path: c.profile_path,
      }))
    }
    return (richDetail.credits?.cast || []) as DetailCast[]
  })()
    .slice()
    .sort((a, b) => (a.order ?? 999) - (b.order ?? 999))
    .slice(0, 30)

  const genres = richDetail.genres || []
  const keywordList = richDetail.keywords?.keywords || richDetail.keywords?.results || []
  const recommendationItems = extractRecommendations(richDetail, tmdbType)

  const productionCompanies = richDetail.production_companies || []
  const productionCountries = richDetail.production_countries || []
  const spokenLanguages = richDetail.spoken_languages || []
  const networks = richDetail.networks || []
  const seasons = safeSeasons

  const mappedOriginalLanguage = mapLanguageCodeToName(detail.originalLanguage, spokenLanguages)
  const mappedOriginCountries =
    (detail.originCountry || [])
      .map(countryCode => mapCountryCodeToName(countryCode))
      .filter(Boolean)
      .join(' / ') || productionCountries.map(country => country.name).join(' / ')

  const coreInfoFields: DetailInfoField[] = [
    { label: '发布日期', value: detail.releaseDate || '' },
    { label: '首播日期', value: richDetail.first_air_date || '' },
    { label: '最后播出', value: richDetail.last_air_date || '' },
    { label: '评分人数', value: formatLargeNumber(detail.voteCount) },
    { label: '热度', value: detail.popularity.toFixed(1) },
    { label: '原始语言', value: mappedOriginalLanguage },
    { label: '原产国家', value: mappedOriginCountries },
    { label: '剧集形式', value: tmdbType === 'tv' ? mapTvTypeLabel(richDetail.type) : '' },
    { label: '分级', value: certFull },
  ].filter(field => field.value)

  const movieInfoFields: DetailInfoField[] = [
    { label: '片长', value: runtimeLabel },
    { label: '预算', value: formatCurrencyUSD(richDetail.budget) },
    { label: '票房', value: formatCurrencyUSD(richDetail.revenue) },
    { label: '系列归属', value: richDetail.belongs_to_collection?.name || '' },
  ].filter(field => field.value)

  const tvInfoFields: DetailInfoField[] = [
    { label: '单集时长', value: runtimeLabel },
    { label: '季数', value: `${Math.max(safeSeasons.filter(s => s.season_number > 0).length, richDetail.number_of_seasons || 0)}` || '' },
    { label: '集数', value: richDetail.number_of_episodes ? `${richDetail.number_of_episodes}` : '' },
    { label: '制作中', value: mapBooleanLabel(richDetail.in_production) },
    {
      label: '最近播出集',
      value: richDetail.last_episode_to_air
        ? `S${richDetail.last_episode_to_air.season_number || '?'}E${richDetail.last_episode_to_air.episode_number || '?'} ${richDetail.last_episode_to_air.name || ''}`
        : '',
    },
    {
      label: '下一待播集',
      value: richDetail.next_episode_to_air
        ? `S${richDetail.next_episode_to_air.season_number || '?'}E${richDetail.next_episode_to_air.episode_number || '?'} ${richDetail.next_episode_to_air.name || ''}`
        : '',
    },
  ].filter(field => field.value)

  const continueWatchingLabel = latestTmdbHistory
    ? latestTmdbHistory.episodeName || `第${latestTmdbHistory.episodeIndex + 1}集`
    : ''
  const continueWatchingProgressLabel = latestTmdbHistory
    ? latestTmdbHistory.duration > 0
      ? `已观看 ${Math.round(
          Math.min(
            100,
            Math.max(
              0,
              (latestTmdbHistory.playbackPosition / latestTmdbHistory.duration) * 100,
            ),
          ),
        )}%`
      : '已开始观看'
    : ''
  const continueWatchingPath = latestTmdbHistory
    ? latestTmdbHistory.sourceCode && latestTmdbHistory.vodId
      ? buildHistoryPlayPath(latestTmdbHistory)
      : buildTmdbPlayPath(tmdbType, detail.id, {
          episodeIndex: latestTmdbHistory.episodeIndex,
          seasonNumber:
            tmdbType === 'tv' ? latestTmdbHistory.tmdbSeasonNumber ?? undefined : undefined,
        })
    : ''

  return (
    <div className="space-y-0">
      <DetailHeroSection
        detail={detail}
        richDetail={richDetail}
        tmdbType={tmdbType}
        releaseYear={releaseYear}
        runtimeLabel={runtimeLabel}
        adultLevel={certShort}
        heroLogo={heroLogo}
        favorited={favorited}
        onBack={() => navigate(TMDB_SEARCH_PATH)}
        onPlayNow={() => navigate(buildTmdbPlayPath(tmdbType, detail.id))}
        onContinueWatching={
          continueWatchingPath ? () => navigate(continueWatchingPath) : undefined
        }
        continueWatchingLabel={continueWatchingLabel}
        continueWatchingProgressLabel={continueWatchingProgressLabel}
        onToggleFavorite={() => toggleTmdbFavorite(mediaSnapshot)}
      />

      <UnderlineTabs
        options={tabItems}
        activeKey={activeTab}
        onChange={setActiveTab}
        layoutId="detail-tab-indicator"
        className="px-2 md:flex md:justify-center md:px-0"
        tabButtonClassName="py-3 text-sm"
        listClassName="gap-4 md:gap-6"
      />

      <div className="mt-6 px-2 pb-6 md:px-3 md:pb-8">
        <AnimatePresence mode="wait" initial={false}>
          <motion.div
            key={activeTab}
            className="space-y-8"
            initial={reducedMotion ? false : { opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={reducedMotion ? undefined : { opacity: 0, y: -6 }}
            transition={reducedMotion ? { duration: 0 } : { duration: 0.2, ease: 'easeOut' }}
          >
            {activeTab === 'overview' && (
              <DetailOverviewTab
                tmdbType={tmdbType}
                genres={genres}
                keywordList={keywordList}
                coreInfoFields={coreInfoFields}
                movieInfoFields={movieInfoFields}
                tvInfoFields={tvInfoFields}
                recommendationItems={recommendationItems}
                translationFields={translationFields}
              />
            )}

            {activeTab === 'playlist' && (
              <DetailPlaylistTab
                tmdbType={tmdbType}
                tmdbId={detail.id}
                loading={playlistMatches.loading}
                error={playlistMatches.error}
                searched={playlistMatches.searched}
                searchedKeyword={playlistMatches.searchedKeyword}
                progress={playlistMatches.progress}
                startedAt={playlistMatches.startedAt}
                completedAt={playlistMatches.completedAt}
                candidates={playlistMatches.candidates}
                movieSourceMatches={playlistMatches.movieSourceMatches}
                seasonSourceMatches={playlistMatches.seasonSourceMatches}
                onRetry={playlistMatches.retry}
              />
            )}

            {activeTab === 'production' && (
              <DetailProductionTab
                tmdbType={tmdbType}
                movieInfoFields={movieInfoFields}
                tvInfoFields={tvInfoFields}
                productionCompanies={productionCompanies}
                productionCountries={productionCountries}
                networks={networks}
              />
            )}

            {activeTab === 'cast' && <DetailCastTab castList={castList} />}

            {activeTab === 'seasons' && <DetailSeasonsTab tmdbType={tmdbType} seasons={seasons} />}

            {activeTab === 'collection' && richDetail.belongs_to_collection?.id && (
              <DetailCollectionTab collectionId={richDetail.belongs_to_collection.id} currentTmdbId={detail.id} currentLabel="当前查看" />
            )}
          </motion.div>
        </AnimatePresence>

        <div className={activeTab === 'resources' ? '' : 'hidden'}>
          <PlayerResourcesTab keyword={detail.title} noScroll />
        </div>
      </div>
    </div>
  )
}

import { useEffect, useState, useRef, useCallback } from 'react'
import { ExternalLink, Copy, Check, Search, AlertCircle, Loader2, ChevronDown, RotateCcw } from 'lucide-react'
import { usePanhubStore } from '@/shared/store/panhubStore'
import { PLATFORM_INFO, type PanhubMergedLinks, type PanhubGenericResponse, type PanhubSearchResponse } from '@/shared/types/panhub'
import { Badge } from '@/shared/components/ui/badge'
import { ScrollArea } from '@/shared/components/ui/scroll-area'
import { cn } from '@/shared/lib/utils'

// ponytail: sessionStorage cache survives page refresh
const CACHE_PREFIX = 'panhub_cache:'
const CACHE_TTL = 24 * 60 * 60 * 1000 // 24h

interface CacheEntry {
  data: PanhubMergedLinks
  ts: number
}

function cacheGet(key: string): PanhubMergedLinks | null {
  try {
    const raw = localStorage.getItem(CACHE_PREFIX + key)
    if (!raw) return null
    const entry: CacheEntry = JSON.parse(raw)
    if (Date.now() - entry.ts > CACHE_TTL) {
      localStorage.removeItem(CACHE_PREFIX + key)
      return null
    }
    return entry.data
  } catch { return null }
}

function cacheSet(key: string, value: PanhubMergedLinks) {
  try {
    const entry: CacheEntry = { data: value, ts: Date.now() }
    localStorage.setItem(CACHE_PREFIX + key, JSON.stringify(entry))
  } catch { /* quota exceeded */ }
}

function cacheKey(keyword: string, plugins: string[]): string {
  return `${keyword.trim()}::${[...plugins].sort().join(',')}`
}

interface PlayerResourcesTabProps {
  keyword: string
  noScroll?: boolean
}

type SearchStatus = 'idle' | 'loading' | 'done' | 'error'

function mergeByType(a: PanhubMergedLinks, b: PanhubMergedLinks): PanhubMergedLinks {
  const out = { ...a }
  for (const type of Object.keys(b)) {
    const existing = out[type] || []
    const seen = new Set(existing.map(x => x.url))
    out[type] = [...existing, ...b[type].filter(item => !seen.has(item.url))]
  }
  return out
}

const formatDate = (d?: string) => {
  if (!d) return ''
  const dt = new Date(d)
  if (isNaN(dt.getTime())) return ''
  const diff = Date.now() - dt.getTime()
  const days = Math.floor(diff / 86400000)
  if (days === 0) return '今天'
  if (days === 1) return '昨天'
  if (days < 7) return `${days}天前`
  return dt.toLocaleDateString('zh-CN')
}

export default function PlayerResourcesTab({ keyword, noScroll }: PlayerResourcesTabProps) {
  const { apiBase, enabledPlugins, concurrency, pluginTimeoutMs } = usePanhubStore()
  const [status, setStatus] = useState<SearchStatus>('idle')
  const [results, setResults] = useState<PanhubMergedLinks>({})
  const [error, setError] = useState('')
  const [copiedUrl, setCopiedUrl] = useState('')
  const [progress, setProgress] = useState({ done: 0, total: 0 })
  const [retryCount, setRetryCount] = useState(0)
  const [collapsedSet, setCollapsedSet] = useState<Set<string>>(new Set())
  const abortRef = useRef<AbortController | null>(null)

  // Keep-Alive: when search config changes (e.g. settings reset), clear stale results and re-search
  const mountedRef = useRef(false)
  useEffect(() => {
    if (!mountedRef.current) { mountedRef.current = true; return }
    abortRef.current?.abort()
    setStatus('idle')
    setResults({})
    setError('')
  }, [apiBase, enabledPlugins, concurrency, pluginTimeoutMs])

  const doSearch = useCallback(async () => {
    if (!keyword.trim() || enabledPlugins.length === 0) {
      setStatus('idle')
      return
    }

    const key = cacheKey(keyword, enabledPlugins)
    const cached = cacheGet(key)
    if (cached) {
      setResults(cached)
      setStatus('done')
      return
    }

    abortRef.current?.abort()
    const controller = new AbortController()
    abortRef.current = controller

    setStatus('loading')
    setError('')
    setResults({})
    setProgress({ done: 0, total: enabledPlugins.length })

    const { default: pLimit } = await import('p-limit')
    const limit = pLimit(concurrency)

    let merged: PanhubMergedLinks = {}
    let hasError = false
    let completed = 0

    const tasks = enabledPlugins.map(plugin =>
      limit(async () => {
        if (controller.signal.aborted) return
        try {
          const ext = JSON.stringify({ __plugin_timeout_ms: pluginTimeoutMs })
          const params = new URLSearchParams({
            kw: keyword.trim(),
            res: 'merged_by_type',
            src: 'plugin',
            conc: '1',
            plugins: plugin,
            ext,
          })
          // pony: external API → proxy through Vite to avoid CORS
          const isExternal = apiBase.startsWith('http')
          const searchUrl = isExternal
            ? `/api/panhub/proxy?target=${encodeURIComponent(apiBase + '/search')}&${params}`
            : `${apiBase}/search?${params}`
          const resp = await fetch(searchUrl, { signal: controller.signal })
          if (!resp.ok) return
          const json: PanhubGenericResponse<PanhubSearchResponse> = await resp.json()
          if (json.code !== 0) return
          const fresh = json.data?.merged_by_type || {}
          merged = mergeByType(merged, fresh)
          setResults({ ...merged })
          // pony: save partial results so cross-page navigation doesn't lose progress
          cacheSet(key, merged)
        } catch (err: unknown) {
          if (err instanceof DOMException && err.name === 'AbortError') return
          hasError = true
        } finally {
          completed++
          setProgress({ done: completed, total: enabledPlugins.length })
        }
      }),
    )

    try {
      await Promise.all(tasks)
      if (controller.signal.aborted) return
      cacheSet(key, merged)
      setResults({ ...merged })
      setStatus(Object.keys(merged).length > 0 || !hasError ? 'done' : 'done')
    } catch {
      if (!controller.signal.aborted) {
        setError('搜索请求失败')
        setStatus('error')
      }
    }
  }, [keyword, apiBase, enabledPlugins, concurrency, pluginTimeoutMs, retryCount])

  useEffect(() => {
    doSearch()
    return () => abortRef.current?.abort()
  }, [doSearch])

  const handleCopy = useCallback(async (url: string) => {
    try {
      await navigator.clipboard.writeText(url)
      setCopiedUrl(url)
      setTimeout(() => setCopiedUrl(''), 1500)
    } catch {
      // clipboard API not available
    }
  }, [])

  const handleRetry = useCallback(() => {
    const key = cacheKey(keyword, enabledPlugins)
    localStorage.removeItem(CACHE_PREFIX + key)
    abortRef.current?.abort()
    setResults({})
    setError('')
    setRetryCount(c => c + 1)
  }, [keyword, enabledPlugins])

  const toggleExpand = useCallback((type: string) => {
    setCollapsedSet(prev => {
      const next = new Set(prev)
      if (next.has(type)) next.delete(type)
      else next.add(type)
      return next
    })
  }, [])

  const platformTypes = Object.keys(results).filter(t => results[t].length > 0)
  const totalCount = platformTypes.reduce((sum, t) => sum + results[t].length, 0)

  const platformList = (
    <div className={noScroll ? 'space-y-3' : 'space-y-3 pr-1'}>
      {platformTypes.map(type => {
        const info = PLATFORM_INFO[type] || PLATFORM_INFO.others
        const items = results[type]
        const collapsed = collapsedSet.has(type)
        return (
          <div
            key={type}
            className="overflow-hidden rounded-lg border border-border/50 bg-card/35"
          >
            <button
              type="button"
              className="flex w-full items-center gap-2.5 border-b border-border/40 px-3 py-2.5 text-left hover:bg-muted/20 transition-colors"
              onClick={() => toggleExpand(type)}
            >
              <div
                className="flex size-7 shrink-0 items-center justify-center rounded-lg"
                style={{ backgroundColor: `${info.color}22` }}
              >
                <img
                  src={info.icon}
                  alt={info.name}
                  className="size-4.5 object-contain"
                />
              </div>
              <span className="text-sm font-semibold">{info.name}</span>
              <Badge variant="outline" className="ml-auto h-5 rounded-full px-2 text-[11px]">
                {items.length}
              </Badge>
              <ChevronDown
                className={cn(
                  'size-4 text-muted-foreground transition-transform',
                  !collapsed && 'rotate-180',
                )}
              />
            </button>

            {!collapsed && (
            <ul className="divide-y divide-border/30">
              {items.map((link, i) => (
                <li key={`${link.url}-${i}`} className="px-3 py-2.5">
                  <div className="flex flex-col gap-1.5">
                    <a
                      href={link.url}
                      target="_blank"
                      rel="noopener noreferrer nofollow"
                      className="group flex items-start gap-1.5 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
                    >
                      <span className="line-clamp-2 flex-1">{link.note || link.url}</span>
                      <ExternalLink className="size-3.5 shrink-0 mt-0.5 opacity-0 group-hover:opacity-100 transition-opacity" />
                    </a>

                    <div className="flex items-center justify-between gap-2">
                      <div className="flex items-center gap-2 text-[11px] text-muted-foreground">
                        {link.datetime && <span>{formatDate(link.datetime)}</span>}
                        {link.password && (
                          <Badge
                            variant="outline"
                            className="h-5 rounded-full px-1.5 text-[10px] border-emerald-400/30 bg-emerald-500/8 text-emerald-600 dark:text-emerald-400"
                          >
                            提取码: {link.password}
                          </Badge>
                        )}
                      </div>

                      <button
                        type="button"
                        className={cn(
                          'flex items-center gap-1 rounded-md px-2 py-1 text-[11px] font-medium transition-colors',
                          copiedUrl === link.url
                            ? 'bg-emerald-500/12 text-emerald-600 dark:text-emerald-400'
                            : 'hover:bg-muted text-muted-foreground hover:text-foreground',
                        )}
                        onClick={() => handleCopy(link.url)}
                      >
                        {copiedUrl === link.url ? (
                          <Check className="size-3" />
                        ) : (
                          <Copy className="size-3" />
                        )}
                        {copiedUrl === link.url ? '已复制' : '复制'}
                      </button>
                    </div>
                  </div>
                </li>
              ))}
            </ul>
            )}
          </div>
        )
      })}
    </div>
  )

  return (
    <div className="space-y-3">
      {status === 'loading' && (
        <div className="flex items-center gap-2 py-4 text-sm text-muted-foreground">
          <Loader2 className="size-4 animate-spin" />
          <span>
            正在搜索 {progress.done}/{progress.total} 个源
            {totalCount > 0 && ` · 已找到 ${totalCount} 个资源`}
          </span>
        </div>
      )}

      {status === 'error' && (
        <div className="flex flex-col gap-2 rounded-lg border border-red-400/35 bg-red-500/10 px-3 py-2.5">
          <div className="flex items-center gap-2 text-sm text-red-500">
            <AlertCircle className="size-4 shrink-0" />
            <span>{error}</span>
          </div>
          <button
            type="button"
            className="inline-flex items-center gap-1.5 self-start rounded-lg border border-red-400/30 px-2.5 py-1 text-xs font-medium text-red-500 hover:bg-red-500/10 transition-colors"
            onClick={handleRetry}
          >
            <RotateCcw className="size-3" />
            重新匹配
          </button>
        </div>
      )}

      {status === 'idle' && !keyword.trim() && (
        <p className="py-4 text-sm text-muted-foreground">输入关键词后可搜索网盘资源</p>
      )}

      {status === 'idle' && keyword.trim() && enabledPlugins.length === 0 && (
        <p className="py-4 text-sm text-muted-foreground">请先在设置中启用至少一个搜索插件</p>
      )}

      {status === 'done' && totalCount === 0 && (
        <div className="flex flex-col items-center gap-3 py-6 text-muted-foreground">
          <Search className="size-8 opacity-40" />
          <p className="text-sm">未找到相关网盘资源</p>
          <p className="text-xs opacity-60">试试缩短关键词或切换搜索插件</p>
          <button
            type="button"
            className="inline-flex items-center gap-1.5 rounded-lg border border-border/60 px-3 py-1.5 text-xs font-medium text-muted-foreground hover:text-foreground hover:border-border transition-colors"
            onClick={handleRetry}
          >
            <RotateCcw className="size-3" />
            重新匹配
          </button>
        </div>
      )}

      {(status === 'done' || status === 'loading') && totalCount > 0 && (
        <>
          <div className="flex items-center gap-2 text-xs text-muted-foreground">
            <Badge variant="secondary" className="h-5 rounded-full px-2 text-[11px]">
              共 {totalCount} 个资源
            </Badge>
          </div>

          {noScroll ? (
            platformList
          ) : (
            <ScrollArea className="max-h-[50vh]">
              {platformList}
            </ScrollArea>
          )}
        </>
      )}
    </div>
  )
}

import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from 'react'
