import { useState, useRef, useEffect, useCallback, useMemo, memo } from 'react'
import { Search, X, History, Trash2, Film, User, Globe, ChevronDown } from 'lucide-react'
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { Input } from '@/shared/components/ui/input'
import { Button } from '@/shared/components/ui/button'
import { Popover, PopoverContent, PopoverAnchor } from '@/shared/components/ui/popover'
import { ScrollArea } from '@/shared/components/ui/scroll-area'
import { useSearchHistory } from '@/shared/hooks'
import type { SearchMode } from './SearchModeToggle'
import type { TmdbMediaItem } from '@/shared/types/tmdb'

export type SearchType = 'media' | 'person'

const HINT_PLACEHOLDER = '使用 y:年份 筛选，如"星球大战 y:1977"'

const SEARCH_TYPE_OPTIONS: { value: SearchType; label: string; icon: React.ReactNode }[] = [
  { value: 'media', label: '影视', icon: <Film className="size-3.5" /> },
  { value: 'person', label: '人物', icon: <User className="size-3.5" /> },
]

const DIRECT_TYPE_OPTIONS: { value: SearchType; label: string; icon: React.ReactNode }[] = [
  { value: 'media', label: '综合', icon: <Globe className="size-3.5" /> },
]

interface SearchHubInputProps {
  initialQuery: string
  initialSearchType: SearchType
  onSearch: (query: string, searchType: SearchType) => void
  onClear?: () => void
  searchMode?: SearchMode
  trending?: TmdbMediaItem[]
  className?: string
}

export const SearchHubInput = memo(function SearchHubInput({
  initialQuery,
  initialSearchType,
  onSearch,
  onClear,
  searchMode,
  trending = [],
  className,
}: SearchHubInputProps) {
  const isDirect = searchMode === 'direct'
  const typeOptions = isDirect ? DIRECT_TYPE_OPTIONS : SEARCH_TYPE_OPTIONS

  // 动态 placeholder：热映按顺序，提示随机穿插
  const placeholders = useMemo(() => {
    if (trending.length === 0) return [HINT_PLACEHOLDER]
    const trendingTitles = trending.slice(0, 8).map(t => `大家都在搜：${t.title}`)
    const result: string[] = []
    for (let i = 0; i < trendingTitles.length; i++) {
      result.push(trendingTitles[i])
      // 每 1~3 条热映后随机穿插一次提示
      if ((i + 1) % (Math.floor(Math.random() * 3) + 1) === 0) {
        result.push(HINT_PLACEHOLDER)
      }
    }
    return result
  }, [trending])
  const [inputValue, setInputValue] = useState(initialQuery)
  const [searchType, setSearchType] = useState<SearchType>(initialSearchType)
  const [isDropdownOpen, setIsDropdownOpen] = useState(false)
  const [typeMenuOpen, setTypeMenuOpen] = useState(false)
  const [placeholderIdx, setPlaceholderIdx] = useState(0)

  const inputRef = useRef<HTMLInputElement>(null)
  const blurTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const { searchHistory, removeSearchHistoryItem } = useSearchHistory()

  const typeBtnRef = useRef<HTMLButtonElement>(null)

  // close type menu on outside click
  useEffect(() => {
    if (!typeMenuOpen) return
    const handler = (e: MouseEvent) => {
      const target = e.target as HTMLElement
      if (typeBtnRef.current?.contains(target)) return
      // check if click is inside the dropdown
      if (target.closest('[data-type-menu]')) return
      setTypeMenuOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [typeMenuOpen])

  // rotating placeholder
  useEffect(() => {
    const timer = setInterval(() => setPlaceholderIdx(i => {
      if (placeholders.length <= 1) return 0
      let next: number
      do { next = Math.floor(Math.random() * placeholders.length) } while (next === i)
      return next
    }), 4000)
    return () => clearInterval(timer)
  }, [])

  useEffect(() => { setInputValue(initialQuery) }, [initialQuery])
  useEffect(() => {
    // 直连模式下强制 media
    setSearchType(isDirect ? 'media' : initialSearchType)
  }, [initialSearchType, isDirect])

  useEffect(() => {
    return () => { if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current) }
  }, [])

  const handleSearch = useCallback((q: string, typeOverride?: SearchType) => {
    const trimmed = q.trim()
    if (!trimmed) return
    const type = typeOverride || searchType
    if (typeOverride) setSearchType(typeOverride)
    setInputValue(trimmed)
    setIsDropdownOpen(false)
    onSearch(trimmed, type)
  }, [onSearch, searchType])

  const handleInputChange = (value: string) => {
    setInputValue(value)
  }

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter') { handleSearch(inputValue) }
    if (event.key === 'Escape') { setIsDropdownOpen(false); inputRef.current?.blur() }
  }

  const handleFocus = () => {
    if (blurTimeoutRef.current) clearTimeout(blurTimeoutRef.current)
    setIsDropdownOpen(true)
  }

  const handleBlur = () => {
    blurTimeoutRef.current = setTimeout(() => { setIsDropdownOpen(false) }, 200)
  }

  const handleClear = () => {
    setInputValue('')
    onClear?.()
    inputRef.current?.focus()
  }

  const hasContent = inputValue.trim().length > 0
  const hasHistory = searchHistory.length > 0
  // 搜索页不需要实时建议，只在无输入时显示历史
  const shouldShowDropdown = isDropdownOpen && !hasContent && hasHistory

  const currentTypeLookup = typeOptions.find(o => o.value === searchType)
  const currentType = currentTypeLookup || typeOptions[0]
  const reducedMotion = useReducedMotion()

  return (
    <div className={`w-full max-w-3xl ${className}`}>
      <Popover open={shouldShowDropdown}>
        <PopoverAnchor asChild>
          <div className="relative flex w-full">
            {/* type selector */}
            <div className="relative">
              <button
                ref={typeBtnRef}
                type="button"
                className="flex h-11 items-center gap-1 rounded-full rounded-r-none border border-input bg-transparent pl-3 pr-2 text-sm font-medium hover:bg-accent/50 transition-colors"
                onClick={(e) => { e.stopPropagation(); setTypeMenuOpen(prev => !prev) }}
              >
                {currentType.icon}
                {currentType.label}
                <ChevronDown className="size-3 text-muted-foreground" />
              </button>
              {typeMenuOpen && (
                <div data-type-menu className="absolute top-full left-0 z-50 mt-1 w-24 rounded-lg border border-border bg-popover p-1 shadow-md">
                  {typeOptions.map(opt => (
                    <button
                      key={opt.value}
                      type="button"
                      className={`flex w-full items-center gap-2 rounded-md px-3 py-2 text-sm transition-colors hover:bg-accent ${opt.value === searchType ? 'text-primary font-medium' : ''}`}
                      onMouseDown={e => e.preventDefault()}
                      onClick={() => { setSearchType(opt.value); setTypeMenuOpen(false); inputRef.current?.focus() }}
                    >
                      {opt.icon}
                      {opt.label}
                    </button>
                  ))}
                </div>
              )}
            </div>
            {/* input */}
            <div className="relative flex-1">
              <Input
                ref={inputRef}
                placeholder=""
                className="h-11 w-full rounded-none border-x-0 pr-8 text-base focus-visible:ring-0"
                value={inputValue}
                onChange={e => handleInputChange(e.target.value)}
                onKeyDown={handleKeyDown}
                onFocus={handleFocus}
                onBlur={handleBlur}
              />
              {!inputValue && (
                <AnimatePresence mode="wait">
                  <motion.span
                    key={placeholderIdx}
                    initial={reducedMotion ? false : { opacity: 0, y: 6 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={reducedMotion ? undefined : { opacity: 0, y: -6 }}
                    transition={reducedMotion ? { duration: 0 } : { duration: 0.25 }}
                    className="text-muted-foreground pointer-events-none absolute top-1/2 left-3 -translate-y-1/2 truncate text-base select-none"
                  >
                    {placeholders[placeholderIdx]}
                  </motion.span>
                </AnimatePresence>
              )}
            </div>
            {inputValue.length > 0 && (
              <button
                type="button"
                onClick={handleClear}
                className="text-muted-foreground hover:text-foreground absolute top-1/2 right-24 -translate-y-1/2 transition-colors"
              >
                <X size={16} />
              </button>
            )}
            <Button
              disabled={inputValue.length === 0}
              className="dark:bg-accent dark:hover:bg-accent/80 h-11 w-20 rounded-full rounded-l-none bg-gray-200 hover:bg-gray-300"
              onClick={() => handleSearch(inputValue)}
            >
              <Search className="text-primary" size={20} />
            </Button>
          </div>
        </PopoverAnchor>

        <PopoverContent
          className="w-[var(--radix-popover-trigger-width)] p-0"
          align="start"
          sideOffset={8}
          onOpenAutoFocus={e => e.preventDefault()}
        >
          <div className="p-1">
            <ScrollArea className="max-h-80 px-3">
              <div>
                <div className="text-muted-foreground px-3 py-2 text-xs font-medium">最近搜索</div>
                {searchHistory.map(item => (
                  <div
                    key={item.id}
                    className="hover:bg-accent group flex cursor-pointer items-center rounded-lg px-3 py-2 transition-colors"
                    onClick={() => handleSearch(item.content, item.searchType as SearchType)}
                    role="button"
                    tabIndex={0}
                    onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); handleSearch(item.content, item.searchType as SearchType) } }}
                  >
                    <History className="text-muted-foreground mr-3 size-4 shrink-0" />
                    <span className="flex-1 truncate">{item.content}</span>
                    {item.searchType && (
                      <span className="text-muted-foreground ml-2 shrink-0 text-[10px]">
                        {item.searchType === 'person' ? '人物' : '影视'}
                      </span>
                    )}
                    <button
                      type="button"
                      className="text-muted-foreground hover:text-destructive shrink-0 p-1 opacity-0 transition-colors group-hover:opacity-100"
                      onMouseDown={e => e.preventDefault()}
                      onClick={e => { e.stopPropagation(); removeSearchHistoryItem(item.id) }}
                    >
                      <Trash2 className="size-4" />
                    </button>
                  </div>
                ))}
              </div>
            </ScrollArea>
          </div>
        </PopoverContent>
      </Popover>
    </div>
  )
})

import type { Plugin } from 'vite'
import {
  handleProxyRequest,
  getProxyTimeoutMs,
  getTargetUrl,
  parseProxyError,
} from '../shared/lib/proxy'

function getSystemProxyUrl(): string | null {
  return process.env.HTTPS_PROXY || process.env.HTTP_PROXY || process.env.https_proxy || process.env.http_proxy || null
}

async function createProxyFetch() {
  const proxyUrl = getSystemProxyUrl()
  if (!proxyUrl) return null

  const { HttpsProxyAgent } = await import('https-proxy-agent')
  const mod = await import('https')

  return (targetUrl: string) => {
    return new Promise<{ status: number; headers: { get: (k: string) => string | undefined }; text: () => Promise<string> }>((resolve, reject) => {
      const u = new URL(targetUrl)
      const agent = new HttpsProxyAgent(proxyUrl)
      const req = mod.get({
        hostname: u.hostname,
        path: u.pathname + u.search,
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/122.0.0.0 Safari/537.36',
          Accept: 'application/json, text/plain, */*',
        },
        agent,
        rejectUnauthorized: false,
        timeout: getProxyTimeoutMs(),
      }, res => {
        let data = ''
        res.on('data', chunk => { data += chunk })
        res.on('end', () => {
          resolve({
            status: res.statusCode ?? 502,
            headers: { get: (k: string) => (res.headers as Record<string, string | undefined>)[k.toLowerCase()] },
            text: () => Promise.resolve(data),
          })
        })
      })
      req.on('error', reject)
      req.on('timeout', () => { req.destroy(); reject(new Error('Proxy timeout')) })
    })
  }
}

export function proxyMiddleware(): Plugin {
  function createProxyHandler() {
    let proxyFetch: ((url: string) => Promise<{ status: number; headers: { get: (k: string) => string | undefined }; text: () => Promise<string> }>) | null = null
    let proxyFetchReady = false

    return async (req: any, res: any, next: any) => {
      if (!req.url?.startsWith('/proxy')) {
        return next()
      }

      try {
        if (!proxyFetchReady) {
          proxyFetch = await createProxyFetch()
          proxyFetchReady = true
        }

        const targetUrl = getTargetUrl(req.url)
        const response = proxyFetch
          ? await proxyFetch(targetUrl)
          : await handleProxyRequest(targetUrl)

        const text = await response.text()
        const contentType = response.headers.get('content-type') || 'application/json'

        res.setHeader('Access-Control-Allow-Origin', '*')
        res.setHeader('Content-Type', contentType)
        res.writeHead(response.status)
        res.end(text)
      } catch (error) {
        const { message, cause } = parseProxyError(error)
        const timeoutMs = getProxyTimeoutMs()
        res.writeHead(500, { 'Content-Type': 'application/json' })
        res.end(JSON.stringify({ error: 'Proxy request failed', message, cause, timeoutMs }))
      }
    }
  }

  return {
    name: 'proxy-middleware',
    configureServer(server) {
      server.middlewares.use(createProxyHandler())
    },
    configurePreviewServer(server) {
      server.middlewares.use(createProxyHandler())
    },
  }
}

import { createApp, createRouter, defineEventHandler, getQuery, sendError, createError, toNodeListener } from 'h3'
import { getOrCreateSearchService } from './core/services'
import channelsConfig from './config/channels.json'
import type { GenericResponse, SearchRequest } from './core/types/models'

function parseList(val: string | undefined): string[] | undefined {
  if (!val) return undefined
  const parts = val.split(',').map(s => s.trim()).filter(Boolean)
  return parts.length ? parts : undefined
}

function getClientAbortSignal(event: any): AbortSignal | undefined {
  const nodeEvent = event as { node?: { req?: any } }
  const req = nodeEvent.node?.req
  if (req && typeof req.on === 'function') {
    const controller = new AbortController()
    req.on('close', () => {
      if (req.destroyed || (req.writableEnded === false && req.readableEnded)) {
        controller.abort()
      }
    })
    return controller.signal
  }
  return undefined
}

const runtimeConfig = {
  priorityChannels: channelsConfig.priorityChannels,
  defaultChannels: channelsConfig.defaultChannels,
  defaultConcurrency: channelsConfig.defaultConcurrency,
  pluginTimeoutMs: channelsConfig.pluginTimeoutMs,
  cacheEnabled: true,
  cacheTtlMinutes: channelsConfig.cacheTtlMinutes,
}

const searchHandler = defineEventHandler(async (event) => {
  const service = getOrCreateSearchService(runtimeConfig)
  const q = getQuery(event)

  const kw = ((q.kw as string) || '').trim()
  if (!kw) {
    return sendError(event, createError({ statusCode: 400, statusMessage: 'kw is required' }))
  }
  if (kw.length > 200) {
    return sendError(event, createError({ statusCode: 400, statusMessage: 'kw too long (max 200)' }))
  }

  let ext: Record<string, any> | undefined
  const extStr = (q.ext as string | undefined)?.trim()
  if (extStr) {
    if (extStr === '{}') ext = {}
    else {
      try { ext = JSON.parse(extStr) }
      catch {
        return sendError(event, createError({ statusCode: 400, statusMessage: 'invalid ext json' }))
      }
    }
  }

  const req: SearchRequest = {
    kw,
    channels: parseList(q.channels as string | undefined),
    conc: (() => {
      const n = q.conc ? parseInt(String(q.conc), 10) : NaN
      return Number.isFinite(n) && n >= 1 && n <= 16 ? n : undefined
    })(),
    refresh: String(q.refresh).trim() === 'true',
    res: (q.res as any) || 'merged_by_type',
    src: (q.src as any) || 'all',
    plugins: parseList(q.plugins as string | undefined),
    cloud_types: parseList(q.cloud_types as string | undefined),
    ext,
  }

  if (req.src === 'tg') req.plugins = undefined
  else if (req.src === 'plugin') req.channels = undefined
  if (!req.res || req.res === 'merge') req.res = 'merged_by_type'

  const signal = getClientAbortSignal(event)

  const { response: result, warnings } = await service.searchWithWarnings(
    req.kw, req.channels, req.conc, !!req.refresh,
    req.res, req.src, req.plugins, req.cloud_types, req.ext || {}, signal,
  )

  const resp: GenericResponse<typeof result> = {
    code: 0,
    message: warnings.length > 0 ? 'partial_success' : 'success',
    data: result,
  }
  if (warnings.length > 0) {
    (resp as any).warnings = warnings
  }
  return resp
})

const healthHandler = defineEventHandler(() => ({
  status: 'ok',
  timestamp: Date.now(),
}))

const router = createRouter()
router.get('/search', searchHandler)
router.get('/health', healthHandler)

export const panhubApp = createApp()
panhubApp.use(router)

export function createPanhubListener() {
  return toNodeListener(panhubApp)
}

import { MemoryCache } from "./memoryCache";
import type { SearchResult } from "../types/models";

/**
 * 缓存命名空间
 */
export enum CacheNamespace {
  TG_SEARCH = "tg",
  PLUGIN_SEARCH = "plugin",
  HOT_SEARCH = "hot_search",
}

/**
 * 统一缓存配置
 */
export interface UnifiedCacheConfig {
  enabled: boolean;
  ttlMinutes: number;
  maxSize?: number;
  maxMemoryBytes?: number;
}

/**
 * 统一缓存管理器
 * 提供命名空间支持和统一的缓存操作
 */
export class UnifiedCache {
  private caches: Map<string, MemoryCache<SearchResult[]>> = new Map();
  private config: UnifiedCacheConfig;
  private namespacePrefix: string;

  constructor(config: UnifiedCacheConfig, namespacePrefix: string = "") {
    this.config = config;
    this.namespacePrefix = namespacePrefix;
  }

  /**
   * 生成完整的缓存键
   */
  private buildKey(namespace: CacheNamespace, key: string): string {
    const prefix = this.namespacePrefix ? `${this.namespacePrefix}:` : "";
    return `${prefix}${namespace}:${key}`;
  }

  /**
   * 获取或创建命名空间对应的缓存实例
   */
  private getCache(namespace: CacheNamespace): MemoryCache<SearchResult[]> {
    const cacheKey = this.namespacePrefix
      ? `${this.namespacePrefix}:${namespace}`
      : namespace;

    if (!this.caches.has(cacheKey)) {
      const cache = new MemoryCache<SearchResult[]>({
        maxSize: this.config.maxSize,
        maxMemoryBytes: this.config.maxMemoryBytes,
      });
      this.caches.set(cacheKey, cache);
    }

    return this.caches.get(cacheKey)!;
  }

  /**
   * 获取缓存
   */
  get(namespace: CacheNamespace, key: string): { hit: boolean; value?: SearchResult[] } {
    if (!this.config.enabled) {
      return { hit: false };
    }

    const cache = this.getCache(namespace);
    const fullKey = this.buildKey(namespace, key);
    return cache.get(fullKey);
  }

  /**
   * 设置缓存
   */
  set(namespace: CacheNamespace, key: string, value: SearchResult[]): void {
    if (!this.config.enabled) {
      return;
    }

    const cache = this.getCache(namespace);
    const fullKey = this.buildKey(namespace, key);
    const ttlMs = this.config.ttlMinutes * 60 * 1000;
    cache.set(fullKey, value, ttlMs);
  }

  /**
   * 删除缓存
   */
  delete(namespace: CacheNamespace, key: string): void {
    const cache = this.getCache(namespace);
    const fullKey = this.buildKey(namespace, key);
    cache.delete(fullKey);
  }

  /**
   * 清空指定命名空间的缓存
   */
  clearNamespace(namespace: CacheNamespace): void {
    const cacheKey = this.namespacePrefix
      ? `${this.namespacePrefix}:${namespace}`
      : namespace;
    const cache = this.caches.get(cacheKey);
    if (cache) {
      cache.clear();
    }
  }

  /**
   * 清空所有缓存
   */
  clearAll(): void {
    this.caches.forEach((cache) => cache.clear());
  }

  /**
   * 获取缓存统计信息
   */
  getStats(): Record<string, any> {
    const stats: Record<string, any> = {
      enabled: this.config.enabled,
      ttlMinutes: this.config.ttlMinutes,
      namespaces: {},
    };

    this.caches.forEach((cache, key) => {
      stats.namespaces[key] = cache.getStats();
    });

    return stats;
  }

  /**
   * 强制清理所有命名空间的缓存
   */
  forceCleanup(): void {
    this.caches.forEach((cache) => cache.forceCleanup());
  }
}

/**
 * 创建搜索缓存实例
 */
export function createSearchCache(config: UnifiedCacheConfig): UnifiedCache {
  return new UnifiedCache(config, "search");
}

