export class NyaaPlugin extends BaseAsyncPlugin {
  constructor() {
    super("nyaa", 4);
  }

  override async search(keyword: string): Promise<SearchResult[]> {
    const html = await ofetch<string>(SEARCH(keyword), {
      headers: {
        "user-agent": "Mozilla/5.0",
        referer: BASE + "/",
      },
      timeout: 10000,
    }).catch(() => "");
    if (!html) return [];
    const $ = load(html);
    const out: SearchResult[] = [];
    const tasks: Promise<void>[] = [];

    $("table tbody tr").each((_, tr) => {
      const row = $(tr);
      const tds = row.find("td");
      if (!tds.length) return;
      const titleA = tds.eq(1).find("a").last();
      const title = (titleA.text() || "").trim();
      if (!title) return;
      const pageHref = titleA.attr("href") || ""; // /view/xxxxxx
      const detail = pageHref.startsWith("/") ? `${BASE}${pageHref}` : pageHref;
      const unique = detail
        ? `nyaa-${detail.split("/").pop()}`
        : `nyaa-${title}`;
      let magnet = row.find("a[href^='magnet:']").attr("href") || "";
      if (!magnet && detail) {
        tasks.push(
          (async () => {
            const mg = await fetchDetailMagnet(detail);
            if (!mg) return;
            out.push({
              message_id: "",
              unique_id: unique,
              channel: "",
              datetime: new Date().toISOString(),
              title,
              content: "",
              links: [{ type: "magnet", url: mg, password: "" }],
            });
          })()
        );
        return;
      }
      if (!magnet) return;
      const size = row.find("td").eq(3).text().trim();
      const seeders = row.find("td").eq(5).text().trim();
      const leechers = row.find("td").eq(6).text().trim();
      const contentParts: string[] = [];
      if (size) contentParts.push(`Size: ${size}`);
      if (seeders) contentParts.push(`Seeders: ${seeders}`);
      if (leechers) contentParts.push(`Leechers: ${leechers}`);

      out.push({
        message_id: "",
        unique_id: unique,
        channel: "",
        datetime: new Date().toISOString(),
        title,
        content: contentParts.join(" | "),
        links: [{ type: "magnet", url: magnet, password: "" }],
      });
    });

    if (tasks.length) await Promise.allSettled(tasks);
    return out;
  }
}

import { BaseAsyncPlugin, registerGlobalPlugin } from "./manager";
import type { SearchResult } from "../types/models";
import { ofetch } from "ofetch";

type ApiItem = {
  vod_id: number;
  vod_name: string;
  vod_actor?: string;
  vod_director?: string;
  vod_down_from?: string;
  vod_down_url?: string;
  vod_remarks?: string;
  vod_pubdate?: string;
  vod_area?: string;
  vod_year?: string;
};

type ApiResponse = { code: number; msg: string; list: ApiItem[] };

const PWD_RE = /\?pwd=([0-9a-zA-Z]+)/;

function mapCloudType(apiType: string, url: string): string {
  const upper = (apiType || "").toUpperCase();
  switch (upper) {
    case "BD":
      return "baidu";
    case "KG":
      return "quark";
    case "UC":
      return "uc";
    case "ALY":
      return "aliyun";
    case "XL":
      return "xunlei";
    case "TY":
      return "tianyi";
    case "115":
      return "115";
    case "MB":
      return "mobile";
    case "WY":
      return "weiyun";
    case "LZ":
      return "lanzou";
    case "JGY":
      return "jianguoyun";
    case "123":
      return "123";
    case "PK":
      return "pikpak";
    default:
      return determineLinkType(url);
  }
}

function determineLinkType(url: string): string {
  const u = url.toLowerCase();
  if (u.includes("pan.quark.cn/s/")) return "quark";
  if (u.includes("drive.uc.cn/s/")) return "uc";
  if (u.includes("pan.baidu.com/s/")) return "baidu";
  if (u.includes("aliyundrive.com/s/") || u.includes("alipan.com/s/"))
    return "aliyun";
  if (u.includes("pan.xunlei.com/s/")) return "xunlei";
  if (u.includes("cloud.189.cn/t/")) return "tianyi";
  if (u.includes("115.com/s/")) return "115";
  if (u.includes("feixin.10086.cn") || u.includes("yun.139.com") || u.includes("caiyun.139.com")) return "mobile";
  if (u.includes("share.weiyun.com")) return "weiyun";
  if (u.includes("lanzou") || u.includes("lanzo")) return "lanzou";
  if (u.includes("jianguoyun.com/p/")) return "jianguoyun";
  if (u.includes("123pan.com/s/")) return "123";
  if (u.includes("mypikpak.com/s/")) return "pikpak";
  if (u.startsWith("magnet:")) return "magnet";
  if (u.startsWith("ed2k://")) return "ed2k";
  return "";
}

function parseLinks(fromStr: string, urlStr: string) {
  const fromParts = (fromStr || "").split("$$$");
  const urlParts = (urlStr || "").split("$$$");
  const min = Math.min(fromParts.length, urlParts.length);
  const links: SearchResult["links"] = [];
  for (let i = 0; i < min; i += 1) {
    const apiType = (fromParts[i] || "").trim();
    const u = (urlParts[i] || "").trim();
    if (!u) continue;
    const type = mapCloudType(apiType, u);
    if (!type) continue;
    const m = u.match(PWD_RE);
    const password = m ? m[1] : "";
    links.push({ type, url: u, password });
  }
  return links;
}

