      const director = s
        .find(".video-info-items .video-info-itemtitle:contains(导演)")
        .siblings(".video-info-actor")
        .text()
        .trim();
      const plot = s
        .find(".video-info-items .video-info-itemtitle:contains(剧情)")
        .siblings(".video-info-item")
        .text()
        .trim();
      const content = [
        quality && `【${quality}】`,
