}

/**
 * 错误类型枚举
 */
export enum ErrorType {
  NETWORK_ERROR = "network_error",
  TIMEOUT_ERROR = "timeout_error",
  PARSE_ERROR = "parse_error",
  PLUGIN_ERROR = "plugin_error",
  VALIDATION_ERROR = "validation_error",
  UNKNOWN_ERROR = "unknown_error",
}

/**
 * 错误严重级别
 */
export enum ErrorSeverity {
  LOW = "low",
  MEDIUM = "medium",
  HIGH = "high",
}

/**
 * 错误详情接口
 */
export interface ErrorDetail {
  type: ErrorType;
  severity: ErrorSeverity;
  message: string;
  source?: string;
  timestamp: number;
}

/**
 * 警告信息接口
 */
export interface WarningInfo {
  type: ErrorType;
  message: string;
  source?: string;
  count: number;
}

/**
 * 分类错误
 */
export function classifyError(error: any, source?: string): ErrorDetail {
  const timestamp = Date.now();
  const msg = typeof error?.message === "string" ? error.message : "";

  // 网络错误
  if (
    error?.code === "ECONNREFUSED" ||
    error?.code === "ENOTFOUND" ||
    error?.code === "ECONNRESET" ||
    msg.includes("network") ||
    msg.includes("ECONN")
  ) {
    return {
      type: ErrorType.NETWORK_ERROR,
      severity: ErrorSeverity.MEDIUM,
      message: `网络连接失败: ${msg || "未知错误"}`,
      source,
      timestamp,
    };
  }

  // 超时错误
  if (
    msg.includes("timeout") ||
    msg.includes("超时")
  ) {
    return {
      type: ErrorType.TIMEOUT_ERROR,
      severity: ErrorSeverity.LOW,
      message: `请求超时: ${msg || "未能在指定时间内完成"}`,
      source,
      timestamp,
    };
  }

  // 解析错误
  if (
    msg.includes("parse") ||
    msg.includes("解析") ||
    error?.name === "SyntaxError"
  ) {
    return {
      type: ErrorType.PARSE_ERROR,
      severity: ErrorSeverity.HIGH,
      message: `数据解析失败: ${msg || "无法解析响应数据"}`,
      source,
      timestamp,
    };
  }

  // 默认未知错误
  return {
    type: ErrorType.UNKNOWN_ERROR,
    severity: ErrorSeverity.MEDIUM,
    message: msg || "未知错误",
    source,
    timestamp,
  };
}

/**
 * 错误收集器
 */
export class ErrorCollector {
  private errors: Map<string, ErrorDetail[]> = new Map();
  private maxErrorsPerSource = 100;

  record(error: ErrorDetail, source?: string): void {
    const key = source || "global";
    const errors = this.errors.get(key) || [];

    errors.push(error);

    // 限制每个来源的错误数量
    if (errors.length > this.maxErrorsPerSource) {
      errors.shift(); // 移除最旧的错误
    }

    this.errors.set(key, errors);
  }

  getErrors(source?: string): ErrorDetail[] {
    if (source) {
      return this.errors.get(source) || [];
    }

    // 返回所有错误
    const allErrors: ErrorDetail[] = [];
    this.errors.forEach((errors) => {
      allErrors.push(...errors);
    });
    return allErrors;
  }

  getWarnings(): WarningInfo[] {
    const warningMap = new Map<string, WarningInfo>();

    this.errors.forEach((errors) => {
      errors.forEach((error) => {
        const key = `${error.type}:${error.source || "unknown"}`;
        const existing = warningMap.get(key);

        if (existing) {
          existing.count++;
        } else {
          warningMap.set(key, {
            type: error.type,
            message: error.message,
            source: error.source,
            count: 1,
          });
        }
      });
    });

    return Array.from(warningMap.values());
  }

  clear(source?: string): void {
    if (source) {
      this.errors.delete(source);
    } else {
      this.errors.clear();
    }
  }

  hasErrors(): boolean {
    return this.errors.size > 0;
  }
}

/**
 * 增强的 fetch 工具函数
 * 提供重试机制、超时控制和统一错误处理
 */

import { ofetch } from "ofetch";
import type { $Fetch } from "ofetch";

function normalizeError(error: unknown): Error {
  if (error instanceof Error) return error;
  if (typeof error === "string") return new Error(error);
  return new Error("Unknown error");
}

export interface FetchWithRetryOptions {
  /** 最大重试次数，默认 3 */
  maxRetries?: number;
  /** 重试间隔基础时间（毫秒），默认 1000 */
  baseDelay?: number;
  /** 是否使用指数退避，默认 true */
  exponentialBackoff?: boolean;
  /** 超时时间（毫秒），默认 8000 */
  timeout?: number;
  /** 请求失败时是否记录警告日志，默认 true */
  logWarnings?: boolean;
  /** 取消信号，客户端断开时中止请求和重试 */
  signal?: AbortSignal;
}

/**
 * 指数退避延迟
 */
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * 带重试机制的 fetch 函数
 *
 * @param url 请求 URL
 * @param options fetch 选项
 * @param retryOptions 重试配置
 * @returns 响应数据
 *
 * @example
 * ```typescript
 * const data = await fetchWithRetry('https://api.example.com/data', {}, {
 *   maxRetries: 3,
 *   timeout: 5000
 * });
 * ```
 */
export async function fetchWithRetry<T = any>(
  url: string,
  options: RequestInit = {},
  retryOptions: FetchWithRetryOptions = {}
): Promise<T> {
  const {
    maxRetries = 3,
    baseDelay = 1000,
    exponentialBackoff = true,
    timeout = 8000,
    signal,
  } = retryOptions;
  void retryOptions.logWarnings;

  const fetcher: $Fetch = ofetch.create({
    timeout,
    headers: {
      "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
      ...options.headers,
    },
    ...options,
  });

  let lastError: Error | null = null;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    // 客户端断开时立即中止，不再重试
    if (signal?.aborted) {
      throw new DOMException("Request was cancelled", "AbortError");
    }

    try {
      const result = await fetcher<T>(url);
      return result;
    } catch (error) {
      lastError = error as Error;

      // 如果是取消信号导致的错误，直接抛出不再重试
      if (signal?.aborted) {
        throw lastError;
      }

      // 4xx 客户端错误不可恢复，立即放弃不做无意义重试
      if ((error as any)?.statusCode >= 400 && (error as any)?.statusCode < 500) {
        throw lastError;
      }

      // 如果是最后一次尝试，抛出错误
      if (attempt === maxRetries) {
        throw lastError;
      }

      // 计算延迟时间
      const delay = exponentialBackoff
        ? baseDelay * Math.pow(2, attempt)
        : baseDelay;

      await sleep(delay);
    }
  }

  // 理论上不会到达这里，但为了类型安全
  throw lastError;
}

/**
 * 安全执行异步操作，捕获错误并返回默认值
 *
 * @param operation 异步操作函数
 * @param fallback 失败时的默认值
 * @param errorLogger 错误日志记录器
 * @returns 操作结果或默认值
 *
 * @example
 * ```typescript
 * const data = await safeExecute(
 *   () => fetchWithRetry('https://api.example.com/data'),
 *   [],
 *   logger
 * );
 * ```
 */
export async function safeExecute<T>(
  operation: () => Promise<T>,
  fallback: T,
  errorLogger?: { error?: (message: string, error: Error) => void }
): Promise<T> {
  try {
    return await operation();
  } catch (error) {
    errorLogger?.error?.("Operation failed", normalizeError(error));
    return fallback;
  }
}

/**
 * 并行执行多个操作，自动处理错误
 *
 * @param operations 异步操作函数数组
 * @param fallback 失败时的默认值
 * @param logger 日志记录器
 * @returns 所有操作的结果数组（包含失败的默认值）
 *
 * @example
 * ```typescript
 * const results = await safeExecuteAll([
 *   () => fetchWithRetry('https://api1.example.com/data'),
 *   () => fetchWithRetry('https://api2.example.com/data'),
 * ], [], logger);
 * ```
 */
export async function safeExecuteAll<T>(
  operations: Array<() => Promise<T>>,
  fallback: T,
  logger?: { error?: (message: string, error: Error) => void }
): Promise<T[]> {
  const promises = operations.map((op) => safeExecute(op, fallback, logger));
  return Promise.all(promises);
}

/**
 * 带连接复用的 fetch 创建器
 * 适用于需要多次请求同一域名的场景
 */
export function createPersistentFetcher(
  options: FetchWithRetryOptions = {}
): $Fetch {
  const { timeout = 8000 } = options;

  return ofetch.create({
    timeout,
    headers: {
      "user-agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
    },
    // 注意：ofetch 在 Node.js 环境下会自动复用连接
    // 如果需要更精细的控制，可以在这里添加 agent 配置
  });
}

/**
 * 结构化日志系统
 * 支持不同级别的日志输出，便于调试和监控
 */

export type LogLevel = "debug" | "info" | "warn" | "error";

const LOG_LEVEL_COLORS = {
  debug: "\x1b[36m", // cyan
  info: "\x1b[32m",  // green
  warn: "\x1b[33m",  // yellow
  error: "\x1b[31m", // red
  reset: "\x1b[0m",
  dim: "\x1b[2m",
  bright: "\x1b[1m",
};

export interface LogOptions {
  level?: LogLevel;
  service?: string;
  enableColors?: boolean;
}

export interface LogMeta {
  [key: string]: any;
}

export class Logger {
  private level: LogLevel;
  private service: string;
  private enableColors: boolean;
  private levelPriority: Record<LogLevel, number> = {
    debug: 0,
    info: 1,
    warn: 2,
    error: 3,
  };

  constructor(options: LogOptions = {}) {
    const rawLevel = options.level || process.env.LOG_LEVEL || "info";
    const validLevels: string[] = ["debug", "info", "warn", "error"];
    this.level = (validLevels.includes(rawLevel) ? rawLevel : "info") as LogLevel;
    this.service = options.service || "panhub";
    this.enableColors = options.enableColors ?? process.env.NODE_ENV !== "production";
  }

  private shouldLog(level: LogLevel): boolean {
    return this.levelPriority[level] >= this.levelPriority[this.level];
  }

  private colorize(text: string, type: LogLevel | "dim" | "bright" | "reset" = "reset"): string {
    if (!this.enableColors) return text;
    const color = LOG_LEVEL_COLORS[type] || LOG_LEVEL_COLORS.reset;
    return `${color}${text}${LOG_LEVEL_COLORS.reset}`;
  }

  private formatMessage(level: LogLevel, message: string, meta?: LogMeta): string {
    const timestamp = new Date().toISOString();

    const parts: string[] = [];

    // 时间戳
    parts.push(this.colorize(`[${timestamp}]`, "dim"));

    // 级别
    parts.push(this.colorize(`[${level.toUpperCase()}]`, level));

    // 服务名
    parts.push(this.colorize(`[${this.service}]`, "bright"));

    // 消息
    parts.push(message);

    // 元数据
    if (meta && Object.keys(meta).length > 0) {
      parts.push(this.colorize(JSON.stringify(meta, null, 2), "dim"));
    }

    return parts.join(" ");
  }

  debug(message: string, meta?: LogMeta): void {
    if (!this.shouldLog("debug")) return;
    console.debug(this.formatMessage("debug", message, meta));
  }

  info(message: string, meta?: LogMeta): void {
    if (!this.shouldLog("info")) return;
    console.info(this.formatMessage("info", message, meta));
  }

  warn(message: string, meta?: LogMeta): void {
    if (!this.shouldLog("warn")) return;
    console.warn(this.formatMessage("warn", message, meta));
  }

  error(message: string, error?: Error | LogMeta): void {
    if (!this.shouldLog("error")) return;
    const meta =
      error instanceof Error
        ? { message: error.message, stack: error.stack, name: error.name }
        : error;
    console.error(this.formatMessage("error", message, meta as LogMeta));
  }

  /**
   * 性能计时开始
   */
  startTimer(label: string): () => void {
    const start = Date.now();
    return () => {
      const elapsed = Date.now() - start;
      this.debug(`${label} 完成`, { elapsedMs: elapsed });
    };
  }

  /**
   * 异步性能计时
   */
  async time<T>(label: string, fn: () => Promise<T>): Promise<T> {
    const endTimer = this.startTimer(label);
    try {
      const result = await fn();
      endTimer();
      return result;
    } catch (error) {
      this.error(`${label} 失败`, error as Error);
      throw error;
    }
  }

  // 创建子 logger
  child(service: string): Logger {
    return new Logger({
      level: this.level,
      service: `${this.service}:${service}`,
      enableColors: this.enableColors,
    });
  }
}

// 默认导出实例
export const logger = new Logger({ service: "main" });

// 工厂函数
export function createLogger(service: string): Logger {
  return new Logger({ service });
}

// 模块专用日志器
export const loggers = {
  search: createLogger("Search"),
  cache: createLogger("Cache"),
  plugin: createLogger("Plugin"),
  tg: createLogger("TG"),
  api: createLogger("API"),
  hotSearch: createLogger("HotSearch"),
  health: createLogger("Health"),
};

const CJK_PATTERN = /[\u3400-\u9fff]/;
// ASCII \u566a\u97f3\u8bcd\u7528 \b \u8fb9\u754c\uff08\u5bf9 ASCII \u751f\u6548\uff09
const NOISE_PATTERN_ASCII =
  /\b(4k|8k|720p|1080p|2160p|hdr|h265|x265|web-dl|webdl|bluray)\b/gi;
// CJK \u566a\u97f3\u8bcd\u4e0d\u80fd\u7528 \b\uff1aJavaScript \u7684 \b \u57fa\u4e8e \w\uff0cCJK \u4e0d\u5c5e\u4e8e \w\uff0c
// \u7528 \b \u4f1a\u5bfc\u81f4 "\u84dd\u5149\u7535\u5f71" \u4e2d\u7684 "\u84dd\u5149" \u6c38\u8fdc\u5339\u914d\u4e0d\u5230\u3002\u76f4\u63a5\u65e0\u8fb9\u754c\u5339\u914d\u3002
const NOISE_PATTERN_CJK = /(\u84dd\u5149|\u675c\u6bd4|\u56fd\u8bed|\u4e2d\u5b57|\u53cc\u5b57|\u5168\u96c6|\u5b8c\u7ed3)/g;
const BRACKET_PATTERN =
  /[\u3010\u3011\u300a\u300b\[\]()\uff08\uff09]/g;
const SPLIT_PATTERN = /[\s/|,，、·:：;；!?？！+]+/g;
const CJK_CONNECTOR_PATTERN = /[\u7684\u4e4b\u4e0e\u548c\u53ca]/g;

export function normalizeSearchKeyword(input: string): string {
  return (input || "").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");
}

export function buildSearchKeywordVariants(keyword: string): string[] {
  const raw = (keyword || "").trim();
  if (!raw) return [];

  const variants: string[] = [];
  const push = (value: string) => {
    const normalized = normalizeSearchKeyword(value);
    if (normalized.length < 2) return;
    if (variants.some((item) => normalizeSearchKeyword(item) === normalized)) return;
    variants.push(value.trim());
  };

  push(raw);

  const cleaned = raw
    .replace(BRACKET_PATTERN, " ")
    .replace(NOISE_PATTERN_ASCII, " ")
    .replace(NOISE_PATTERN_CJK, " ");
  push(cleaned);

  const compact = cleaned.replace(SPLIT_PATTERN, " ");
  push(compact);

  if (CJK_PATTERN.test(raw)) {
    const cjkParts = cleaned
      .replace(CJK_CONNECTOR_PATTERN, " ")
      .split(SPLIT_PATTERN)
      .map((part) => part.trim())
      .filter(Boolean);

    if (cjkParts.length > 1) {
      push(cjkParts.join(" "));
    }

    for (const part of cjkParts) {
      push(part);
    }
  }

  return variants.slice(0, 6);
}

export function matchesSearchKeyword(text: string, keyword: string): boolean {
  const source = (text || "").trim();
  if (!keyword.trim()) return true;
  if (!source) return false;

  const normalizedSource = normalizeSearchKeyword(source);
  if (!normalizedSource) return false;

  return buildSearchKeywordVariants(keyword).some((variant) =>
    normalizedSource.includes(normalizeSearchKeyword(variant))
  );
}

import { useEffect, useRef, useState } from 'react'
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { ChevronUp } from 'lucide-react'
import { useLocation } from 'react-router'
import { Button } from '@/shared/components/ui/button'
import { useIsMobile } from '@/shared/hooks/use-mobile'
import { cn } from '@/shared/lib'

interface BackToTopButtonProps {
  /** 触发显示按钮的滚动阈值（像素） */
  threshold?: number
  /** ScrollArea 根节点选择器 */
  scrollRootSelector: string
  className?: string
}

const getScrollTop = (target: HTMLElement | Window): number => {
  return target instanceof Window ? target.scrollY : target.scrollTop
}

const scrollToTop = (target: HTMLElement | Window) => {
  if (target instanceof Window) {
    target.scrollTo({ top: 0, behavior: 'smooth' })
    return
  }
  target.scrollTo({ top: 0, behavior: 'smooth' })
}

/**
 * BackToTopButton - 全局回到顶部按钮
 * 监听主滚动容器，在滚动超过阈值后显示
 */
export default function BackToTopButton({
  threshold = 280,
  scrollRootSelector,
  className,
}: BackToTopButtonProps) {
  const location = useLocation()
  const isMobile = useIsMobile()
  const reducedMotion = useReducedMotion()
  const [scrollTarget, setScrollTarget] = useState<HTMLElement | Window | null>(null)
  const [visible, setVisible] = useState(false)
  const [navVisible, setNavVisible] = useState(true)
  const lastScrollY = useRef(0)

  useEffect(() => {
    const root = document.querySelector<HTMLElement>(scrollRootSelector)
    const viewport = root?.querySelector<HTMLElement>('[data-slot="scroll-area-viewport"]')
    setScrollTarget(viewport ?? window)
  }, [scrollRootSelector])

  useEffect(() => {
    if (!scrollTarget) return

    const handleScroll = () => {
      const y = getScrollTop(scrollTarget)
      setVisible(y > threshold)
      if (isMobile) {
        if (y < 0) return
        if (y > lastScrollY.current + 8) setNavVisible(false)
        else if (y < lastScrollY.current - 4) setNavVisible(true)
        lastScrollY.current = y
      }
    }

    handleScroll()
    scrollTarget.addEventListener('scroll', handleScroll, { passive: true })

    return () => {
      scrollTarget.removeEventListener('scroll', handleScroll)
    }
  }, [scrollTarget, threshold])

  useEffect(() => {
    if (!scrollTarget) return

    if (scrollTarget instanceof Window) {
      scrollTarget.scrollTo({ top: 0 })
    } else {
      scrollTarget.scrollTop = 0
    }

    setVisible(false)
  }, [location.pathname, scrollTarget])

  return (
    <div
      className={cn(
        'pointer-events-none absolute right-4 z-40 transition-[bottom] duration-220 ease-out md:right-6',
        isMobile ? (navVisible ? 'bottom-20' : 'bottom-6') : 'bottom-6 md:bottom-8',
        className,
      )}
    >
      <AnimatePresence>
        {visible && scrollTarget && (
          <motion.div
            initial={reducedMotion ? false : { opacity: 0, y: 8, scale: 0.92 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={reducedMotion ? undefined : { opacity: 0, y: 8, scale: 0.92 }}
            transition={reducedMotion ? { duration: 0 } : { duration: 0.2, ease: 'easeOut' }}
            className="pointer-events-auto"
          >
            <Button
              type="button"
              size="icon-lg"
              variant="outline"
              aria-label="回到顶部"
              title="回到顶部"
              className="bg-background/90 rounded-full shadow-lg backdrop-blur-sm"
              onClick={() => scrollToTop(scrollTarget)}
            >
              <ChevronUp className="size-6" />
            </Button>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  )
}

import { Component, type ReactNode } from 'react'
import { useEffect, useState } from 'react'
import { OkiLogo } from '@/shared/components/icons'
import { ChangelogDialog } from '@/shared/components/changelog'
import { useVersionStore } from '@/shared/store/versionStore'

interface Props {
  children: ReactNode
  fallback?: ReactNode
}

interface State {
  error: Error | null
  isChunkError: boolean
}

function isChunkLoadError(error: unknown): boolean {
  return (
    error instanceof TypeError &&
    error.message.includes('Failed to fetch dynamically imported module')
  )
}

/** 开发/测试用：?chunk-error 触发模拟 chunk 加载失败 */
function DevChunkErrorTrigger({ enabled }: { enabled: boolean }) {
  if (enabled) {
    throw new TypeError('Failed to fetch dynamically imported module: /assets/UnifiedPlayer-test.js')
  }
  return null
}

/** chunk 加载失败时展示版本日志，关闭后重载 */
function ChunkErrorFallback({ onReload }: { onReload: () => void }) {
  const [isOpen, setIsOpen] = useState(true)
  const [loaded, setLoaded] = useState(false)
  const { updateHistory, loadUpdateHistory } = useVersionStore()

  useEffect(() => {
    loadUpdateHistory().finally(() => setLoaded(true))
  }, [loadUpdateHistory])

  if (!loaded) {
    return (
      <div className="flex h-dvh items-center justify-center bg-background">
        <OkiLogo size={64} className="animate-pulse" />
      </div>
    )
  }

  return (
    <ChangelogDialog
      isOpen={isOpen}
      onClose={() => {
        setIsOpen(false)
        onReload()
      }}
      versions={updateHistory}
    />
  )
}

export default class ErrorBoundary extends Component<Props, State> {
  constructor(props: Props) {
    super(props)
    this.state = { error: null, isChunkError: false }
  }

  static getDerivedStateFromError(error: Error): State {
    return { error, isChunkError: isChunkLoadError(error) }
  }

  handleReload = () => {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.getRegistrations().then((registrations) => {
        registrations.forEach((reg) => reg.unregister())
        window.location.reload()
      })
    } else {
      window.location.reload()
    }
  }

  render() {
    if (this.state.error) {
      if (this.props.fallback) return this.props.fallback

      if (this.state.isChunkError) {
        return <ChunkErrorFallback onReload={this.handleReload} />
      }

      return (
        <div className="flex h-dvh items-center justify-center bg-background">
          <div className="flex flex-col items-center gap-4 px-6 text-center">
            <OkiLogo size={64} />
            <div>
              <p className="text-lg font-semibold text-foreground">出了点问题</p>
              <p className="text-muted-foreground mt-1 text-sm">
                页面遇到了意外错误，请尝试刷新
              </p>
            </div>
            <button
              onClick={this.handleReload}
              className="bg-primary text-primary-foreground hover:bg-primary/90 rounded-lg px-6 py-2 text-sm font-medium transition-colors"
            >
              刷新页面
            </button>
          </div>
        </div>
      )
    }

    return (
      <>
        <DevChunkErrorTrigger enabled={window.location.search.includes('chunk-error')} />
        {this.props.children}
      </>
    )
  }
}

import { useState, useEffect, useRef, useCallback } from 'react'
import { createPortal } from 'react-dom'
import { useGlobalContextMenuStore } from '@/shared/store/contextMenuStore'
import { cn } from '@/shared/lib/utils'

interface GlobalContextMenuProps {
  children: React.ReactNode
  builtInItems?: Array<{
    id: string
    label: string
    icon?: React.ReactNode
    onClick: () => void
    variant?: 'default' | 'destructive'
    disabled?: boolean
  }>
}

/**
 * 全局右键菜单。
 *
 * 不使用 Radix ContextMenu（其嵌套 Root + Trigger 的事件模型在菜单
 * 已打开时重复右键会泄漏浏览器原生菜单）。改为原生 document capture
 * 阶段监听 contextmenu，仅在非卡片区域弹出定位菜单。
 */
export function GlobalContextMenu({ children, builtInItems }: GlobalContextMenuProps) {
  const dynamicItems = useGlobalContextMenuStore((s) => s.items)
  const [open, setOpen] = useState(false)
  const [point, setPoint] = useState({ x: 0, y: 0 })
  const menuRef = useRef<HTMLDivElement>(null)
  const [focused, setFocused] = useState(false)

  const closeMenu = useCallback(() => {
    setOpen(false)
    setFocused(false)
  }, [])

  // 不聚焦时 3 秒后自动关闭；聚焦（hover）时取消计时
  useEffect(() => {
    if (!open || focused) return
    const timer = setTimeout(closeMenu, 3000)
    return () => clearTimeout(timer)
  }, [open, focused, closeMenu])

  useEffect(() => {
    let longPressTimer: ReturnType<typeof setTimeout> | null = null
    let longPressPos = { x: 0, y: 0 }

    const showMenu = (_target: Element, x: number, y: number) => {
      // 卡片区域由 Radix ContextMenu 接管，全局菜单不介入
      if (_target.closest('[data-slot="context-menu-trigger"]')) return
      if (_target.closest('[role="menu"]')) return
      // 已打开旧菜单 → 先关再开（React 18 自动批量，同帧 close→open）
      setOpen(false)
      setPoint({ x, y })
      setOpen(true)
    }

    const onContextMenu = (e: MouseEvent) => {
      const target = e.target
      if (!(target instanceof Element)) return

      if (target.closest('[data-slot="context-menu-trigger"]')) return
      if (target.closest('[role="menu"]')) {
        e.preventDefault()
        return
      }

      e.preventDefault()
      showMenu(target, e.clientX, e.clientY)
    }

    // iOS touch long-press fallback：Safari 不会在普通元素上触发 contextmenu 事件
    const onTouchStart = (e: TouchEvent) => {
      if (e.touches.length !== 1) return
      const touch = e.touches[0]
      const touchedEl = e.target
      longPressPos = { x: touch.clientX, y: touch.clientY }
      longPressTimer = setTimeout(() => {
        const target = touchedEl
        if (!(target instanceof Element)) return

        // 卡片级 ContextMenuTrigger：补发合成 contextmenu 让 Radix 接管
        if (target.closest('[data-slot="context-menu-trigger"]')) {
          target.dispatchEvent(
            new MouseEvent('contextmenu', {
              bubbles: true,
              cancelable: true,
              clientX: longPressPos.x,
              clientY: longPressPos.y,
            }),
          )
          return
        }

        showMenu(target, longPressPos.x, longPressPos.y)
      }, 500)
    }

    const onTouchMove = (e: TouchEvent) => {
      if (!longPressTimer) return
      const touch = e.touches[0]
      if (touch) {
        const dx = touch.clientX - longPressPos.x
        const dy = touch.clientY - longPressPos.y
        if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
          clearTimeout(longPressTimer)
          longPressTimer = null
        }
      }
    }

    const onTouchEnd = () => {
      if (longPressTimer) {
        clearTimeout(longPressTimer)
        longPressTimer = null
      }
    }

    const onPointerDown = (e: PointerEvent) => {
      if (menuRef.current && !menuRef.current.contains(e.target as Node)) {
        closeMenu()
      }
    }

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') closeMenu()
    }

    document.addEventListener('contextmenu', onContextMenu, true)
    document.addEventListener('touchstart', onTouchStart, { passive: true })
    document.addEventListener('touchmove', onTouchMove, { passive: true })
    document.addEventListener('touchend', onTouchEnd)
    document.addEventListener('touchcancel', onTouchEnd)
    document.addEventListener('pointerdown', onPointerDown, true)
    document.addEventListener('keydown', onKeyDown, true)

    return () => {
      document.removeEventListener('contextmenu', onContextMenu, true)
      document.removeEventListener('touchstart', onTouchStart)
      document.removeEventListener('touchmove', onTouchMove)
      document.removeEventListener('touchend', onTouchEnd)
      document.removeEventListener('touchcancel', onTouchEnd)
      document.removeEventListener('pointerdown', onPointerDown, true)
      document.removeEventListener('keydown', onKeyDown, true)
    }
  }, [])

  const handleItemClick = useCallback((onClick: () => void) => {
    onClick()
    setOpen(false)
  }, [])

  const hasBuiltIn = (builtInItems?.length ?? 0) > 0
  const hasDynamic = dynamicItems.length > 0

  return (
    <>
      {children}
      {open && createPortal(
        <div
          ref={menuRef}
          role="menu"
          onMouseEnter={() => setFocused(true)}
          onMouseLeave={() => setFocused(false)}
          className={cn(
            'bg-popover text-popover-foreground fixed z-[9999]',
            'min-w-[8rem] overflow-x-hidden overflow-y-auto rounded-md border p-1 shadow-md',
            'animate-in fade-in-0 zoom-in-95',
          )}
          style={{
            ...(point.x > window.innerWidth - 200
              ? { right: `${window.innerWidth - point.x}px` }
              : { left: `${point.x}px` }),
            ...(point.y > window.innerHeight - 240
              ? { bottom: `${window.innerHeight - point.y}px` }
              : { top: `${point.y}px` }),
            maxHeight: 'var(--radix-context-menu-content-available-height, auto)',
          }}
        >
          {!hasBuiltIn && !hasDynamic ? (
            <MenuItem disabled>无可用操作</MenuItem>
          ) : (
            <>
              {builtInItems?.map((item) => (
                <MenuItem
                  key={item.id}
                  disabled={item.disabled}
                  variant={item.variant}
                  onClick={() => handleItemClick(item.onClick)}
                >
                  {item.icon}
                  {item.label}
                </MenuItem>
              ))}
              {hasBuiltIn && hasDynamic && <div className="bg-border -mx-1 my-1 h-px" />}
              {dynamicItems.map((item) => (
                <MenuItem
                  key={item.id}
                  disabled={item.disabled}
                  variant={item.variant}
                  onClick={() => handleItemClick(item.onClick)}
                >
                  {item.icon}
                  {item.label}
                </MenuItem>
              ))}
            </>
          )}
        </div>,
        document.body,
      )}
    </>
  )
}

/** 菜单项 — 复用 ContextMenuItem 的视觉样式 */
function MenuItem({
  children,
  disabled,
  variant = 'default',
  onClick,
}: {
  children: React.ReactNode
  disabled?: boolean
  variant?: 'default' | 'destructive'
  onClick?: () => void
}) {
  const handleClick = onClick
    ? (e: React.MouseEvent) => {
        if (e.button !== 0) return
        onClick()
      }
    : undefined

  return (
    <button
      role="menuitem"
      disabled={disabled}
      onClick={handleClick}
      className={cn(
        'focus:bg-accent focus:text-accent-foreground',
        'data-[variant=destructive]:text-destructive data-[variant=destructive]:focus:bg-destructive/10 dark:data-[variant=destructive]:focus:bg-destructive/20 data-[variant=destructive]:focus:text-destructive',
        '[&_svg:not([class*="text-"])]:text-muted-foreground',
        'relative flex w-full cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none',
        'data-[disabled]:pointer-events-none data-[disabled]:opacity-50',
        '[&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*="size-"])]:size-4',
      )}
      data-variant={variant}
    >
      {children}
    </button>
  )
}
